/* ============================================================
   بذر الأشهر التاريخية (يناير–يوليو 2026) — من دفتر السجل الذي زوّدنا به سند.
   يعمل مرة واحدة فقط: يتحقق من عدم وجود الشهر مسبقًا قبل إضافته، بحيث
   لا يكرر البيانات إذا أُعيد تشغيل التطبيق أو كان هناك بيانات محفوظة سلفًا.
   بيانات هذه الأشهر "ربح إجمالي فقط" (بدون تفصيل مبيعات/تكلفة منفصل) —
   هذا هو الشكل المتاح من دفتر السجل لهذه الفترة.
============================================================ */
const HISTORICAL_MONTHS_SEED = [
  { periodLabel: "2026-01", displayLabel: "يناير 2026", sales: 59035, cost: 29215, grossProfit: 29820, expenses: 8065 },
  { periodLabel: "2026-02", displayLabel: "فبراير 2026", sales: 59715, cost: 30780, grossProfit: 28935, expenses: 16290 },
  { periodLabel: "2026-03", displayLabel: "مارس 2026", sales: 127175, cost: 64685, grossProfit: 62490, expenses: 11110 },
  { periodLabel: "2026-04", displayLabel: "أبريل 2026", sales: 91465, cost: 46605, grossProfit: 44860, expenses: 11230 },
  { periodLabel: "2026-05", displayLabel: "مايو 2026", sales: 125250, cost: 65435, grossProfit: 59815, expenses: 11390 },
  { periodLabel: "2026-06", displayLabel: "يونيو 2026", sales: 100945, cost: 50425, grossProfit: 50520, expenses: 11440 },
  { periodLabel: "2026-07", displayLabel: "يوليو 2026", sales: 89130, cost: 45940, grossProfit: 43190, expenses: 11670 },
];

function seedHistoricalMonths(db) {
  let changed = false;
  for (const s of HISTORICAL_MONTHS_SEED) {
    const existing = db.periodClosures.find((p) => p.periodLabel === s.periodLabel);
    if (existing) {
      if (existing.isHistorical && existing.sales == null && s.sales != null) {
        existing.sales = s.sales;
        existing.cost = s.cost;
        changed = true;
      }
      continue;
    }
    const netProfit = s.grossProfit - s.expenses;
    db.periodClosures.push({
      id: uid(), periodLabel: s.periodLabel, displayLabel: s.displayLabel,
      netProfit, sales: s.sales ?? null, cost: s.cost ?? null, grossProfit: s.grossProfit, expenses: s.expenses,
      isHistorical: true, closedAt: nowISO(),
    });
    for (const p of db.partners) {
      const share = (netProfit * p.percentage) / 100;
      db.partnerTransactions.push({
        id: uid(), ts: nowISO(), partnerId: p.id, type: "accrued", amount: share,
        periodLabel: s.periodLabel, notes: `ربح تاريخي — ${s.displayLabel}`,
      });
    }
    changed = true;
  }
  return changed;
}

/* ============================================================
   دوال منطق المخزون والتكلفة — القلب الحسابي للنظام
============================================================ */
function getCurrentQty(db, variantId) {
  for (let i = db.movements.length - 1; i >= 0; i--) {
    if (db.movements[i].variantId === variantId) return db.movements[i].qtyAfter;
  }
  return 0;
}
function findVariant(db, variantId) {
  for (const p of db.products) {
    const v = p.variants.find((v) => v.id === variantId);
    if (v) return { product: p, variant: v };
  }
  return null;
}
function allVariants(db) {
  const out = [];
  for (const p of db.products) {
    for (const v of p.variants) {
      out.push({ product: p, variant: v, qty: getCurrentQty(db, v.id) });
    }
  }
  return out;
}
function pushMovement(db, { variantId, type, qtyChange, unitCost, ref, notes }) {
  const qtyBefore = getCurrentQty(db, variantId);
  const qtyAfter = qtyBefore + qtyChange;
  db.movements.push({
    id: uid(), ts: nowISO(), variantId, type, qtyBefore, qtyChange, qtyAfter,
    unitCost: unitCost ?? null, ref: ref || "", notes: notes || "",
  });
  return qtyAfter;
}
function applyMovingAverage(variant, qtyReceived, unitCost) {
  const qtyBefore = variant._qtyBeforeReceipt ?? 0;
  const totalQty = qtyBefore + qtyReceived;
  if (totalQty <= 0) return unitCost;
  const newAvg = (qtyBefore * (variant.costAvg || 0) + qtyReceived * unitCost) / totalQty;
  return Math.round(newAvg * 100) / 100;
}

function alreadyReturnedQty(db, invoiceId, variantId) {
  let total = 0;
  for (const r of db.returns) {
    if (r.originalInvoiceId !== invoiceId) continue;
    for (const l of r.lines) if (l.variantId === variantId) total += l.qty;
  }
  return total;
}

function monthKey(ts) {
  const d = new Date(ts);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`;
}
function currentMonthKey() {
  return monthKey(nowISO());
}
function computeMonthFinancials(db, periodLabel) {
  const invoices = db.invoices.filter((i) => monthKey(i.ts) === periodLabel);
  const returns = db.returns.filter((r) => monthKey(r.ts) === periodLabel);
  const expenses = db.expenses.filter((e) => monthKey(e.ts) === periodLabel);

  const grossSales = invoices.reduce((s, i) => s + i.total, 0);
  const cogs = invoices.reduce((s, i) => s + i.lines.reduce((s2, l) => s2 + l.cost * l.qty, 0), 0);
  const returnsAmount = returns.reduce((s, r) => s + r.total, 0);
  const returnsCogs = returns.reduce((s, r) => s + r.lines.reduce((s2, l) => s2 + (l.unitCost || 0) * l.qty, 0), 0);

  const netSales = grossSales - returnsAmount;
  const grossProfit = (grossSales - cogs) - (returnsAmount - returnsCogs);
  const totalExpenses = expenses.reduce((s, e) => s + Number(e.amount), 0);
  const netProfit = grossProfit - totalExpenses;

  return { grossSales, netSales, cogs, grossProfit, totalExpenses, netProfit, invoiceCount: invoices.length };
}
function partnerBalance(db, partnerId) {
  return db.partnerTransactions
    .filter((t) => t.partnerId === partnerId)
    .reduce((s, t) => s + (t.type === "accrued" || t.type === "funding" ? t.amount : -t.amount), 0);
}

/* ============================================================
   سجل الشريك — استحقاقات كل شهر مقابل المدفوع فعليًا، شهر بشهر
   (المدفوعات مو مربوطة بشهر معيّن وقت تسجيلها، فنوزّعها FIFO —
   أقدم استحقاق غير مسدد يُسدَّد أول من أي دفعة جديدة، بنفس منطق كشف حساب عادي)
============================================================ */
function computePartnerHistory(db, partnerId) {
  const accruals = (db.partnerTransactions || [])
    .filter((t) => t.partnerId === partnerId && t.type === "accrued")
    .sort((a, b) => (a.periodLabel || "").localeCompare(b.periodLabel || ""));

  const paidTxns = (db.partnerTransactions || []).filter((t) => t.partnerId === partnerId && t.type === "paid");
  // دفعات مربوطة بشهر معيّن (المستخدم اختار يدفع شهر بعينه) — تُطرح من نفس الشهر مباشرة
  const explicitPaidByPeriod = {};
  for (const t of paidTxns) {
    if (t.periodLabel) explicitPaidByPeriod[t.periodLabel] = (explicitPaidByPeriod[t.periodLabel] || 0) + t.amount;
  }
  // دفعات عامة (مو مربوطة بشهر) — تُوزَّع FIFO على أقدم شهر متبقي أول
  let genericPaidPool = paidTxns.filter((t) => !t.periodLabel).reduce((s, t) => s + t.amount, 0);

  const rows = accruals.map((a) => {
    const explicitPaid = Math.min(a.amount, explicitPaidByPeriod[a.periodLabel] || 0);
    let afterExplicit = a.amount - explicitPaid;
    const genericApplied = Math.max(0, Math.min(genericPaidPool, afterExplicit));
    genericPaidPool -= genericApplied;
    const totalPaid = explicitPaid + genericApplied;
    const remaining = a.amount - totalPaid;
    const [y, m] = (a.periodLabel || "").split("-");
    const displayLabel = (y && m) ? `${ARABIC_MONTHS[Number(m) - 1] || m} ${y}` : (a.periodLabel || "—");
    return {
      periodLabel: a.periodLabel,
      displayLabel,
      accrued: a.amount,
      paid: totalPaid,
      remaining,
      status: remaining <= 0.01 ? "paid" : totalPaid > 0.01 ? "partial" : "unpaid",
    };
  });

  return { rows, extraPaid: Math.max(0, genericPaidPool) };
}

/* ============================================================
   تقرير الأرباح — يوحّد الأشهر المُدخَلة تاريخيًا مع الأشهر الحيّة
   (المحسوبة مباشرة من الفواتير والمصروفات) في جدول واحد
============================================================ */
function getAllPeriodRows(db) {
  const rows = {};
  for (const p of db.periodClosures) {
    rows[p.periodLabel] = {
      periodLabel: p.periodLabel,
      displayLabel: p.displayLabel || p.periodLabel,
      sales: p.sales || 0, cogs: p.cost || 0, expenses: p.expenses || 0,
      netProfit: p.netProfit || 0, closed: true,
    };
  }
  const liveKeys = new Set();
  db.invoices.forEach((i) => liveKeys.add(monthKey(i.ts)));
  db.expenses.forEach((e) => liveKeys.add(monthKey(e.ts)));
  db.returns.forEach((r) => liveKeys.add(monthKey(r.ts)));
  for (const mk of liveKeys) {
    if (rows[mk]) continue;
    const fin = computeMonthFinancials(db, mk);
    const [y, m] = mk.split("-");
    rows[mk] = {
      periodLabel: mk, displayLabel: `${ARABIC_MONTHS[Number(m) - 1]} ${y}`,
      sales: fin.netSales, cogs: fin.cogs, expenses: fin.totalExpenses,
      netProfit: fin.netProfit, closed: false,
    };
  }
  return Object.values(rows).sort((a, b) => a.periodLabel.localeCompare(b.periodLabel));
}
function sumRows(rows) {
  return rows.reduce((acc, r) => ({
    sales: acc.sales + (r.sales || 0), cogs: acc.cogs + (r.cogs || 0),
    expenses: acc.expenses + (r.expenses || 0), netProfit: acc.netProfit + (r.netProfit || 0),
  }), { sales: 0, cogs: 0, expenses: 0, netProfit: 0 });
}
function aggregateByQuarter(rows) {
  const groups = {};
  for (const r of rows) {
    const [y, m] = r.periodLabel.split("-");
    const q = Math.ceil(Number(m) / 3);
    const key = `${y}-Q${q}`;
    if (!groups[key]) groups[key] = { key, displayLabel: `الربع ${q} — ${y}`, sales: 0, cogs: 0, expenses: 0, netProfit: 0 };
    groups[key].sales += r.sales || 0; groups[key].cogs += r.cogs || 0;
    groups[key].expenses += r.expenses || 0; groups[key].netProfit += r.netProfit || 0;
  }
  return Object.values(groups).sort((a, b) => a.key.localeCompare(b.key));
}
function aggregateByYear(rows) {
  const groups = {};
  for (const r of rows) {
    const y = r.periodLabel.split("-")[0];
    if (!groups[y]) groups[y] = { key: y, displayLabel: y, sales: 0, cogs: 0, expenses: 0, netProfit: 0 };
    groups[y].sales += r.sales || 0; groups[y].cogs += r.cogs || 0;
    groups[y].expenses += r.expenses || 0; groups[y].netProfit += r.netProfit || 0;
  }
  return Object.values(groups).sort((a, b) => a.key.localeCompare(b.key));
}

