/* ============================================================
   نقطة البيع
============================================================ */
function POSView({ db, update, openShift, showToast, displayName, role }) {
  const [query, setQuery] = useState("");
  const [cart, setCart] = useState([]); // {lineId, variantId, name, sku, qty, price, cost, costPending, isQuickItem}
  const [payments, setPayments] = useState([{ method: "كاش", amount: 0 }]);
  const [quickAddOpen, setQuickAddOpen] = useState(false);
  const [quickName, setQuickName] = useState("");
  const [quickPrice, setQuickPrice] = useState("");
  const [quickCost, setQuickCost] = useState("");
  const [customerName, setCustomerName] = useState("");
  const [customerPhone, setCustomerPhone] = useState("");
  const [lastReceipt, setLastReceipt] = useState(null);
  const submittingSaleRef = useRef(false);

  const customerSuggestions = useMemo(() => {
    const p = customerPhone.trim();
    if (!p || p.length < 2) return [];
    return (db.customers || []).filter((c) => c.phone.includes(p)).slice(0, 5);
  }, [db.customers, customerPhone]);

  const variants = useMemo(() => allVariants(db), [db]);
  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return variants.slice(0, 24);
    return variants.filter(
      (v) =>
        v.product.name.toLowerCase().includes(q) ||
        v.variant.sku.toLowerCase().includes(q) ||
        (v.variant.attrLabel || "").toLowerCase().includes(q)
    ).slice(0, 40);
  }, [variants, query]);

  const total = cart.reduce((s, l) => s + l.qty * l.price, 0);
  const paid = payments.reduce((s, p) => s + (Number(p.amount) || 0), 0);

  function addToCart(v) {
    if (v.qty <= 0) {
      showToast("⚠ لا يوجد رصيد متاح لهذا الصنف", "err");
      return;
    }
    setCart((prev) => {
      const existing = prev.find((l) => l.variantId === v.variant.id);
      if (existing) {
        if (existing.qty + 1 > v.qty) {
          showToast("⚠ الكمية المطلوبة تتجاوز الرصيد المتاح", "err");
          return prev;
        }
        return prev.map((l) => (l.variantId === v.variant.id ? { ...l, qty: l.qty + 1 } : l));
      }
      return [...prev, {
        lineId: uid(), variantId: v.variant.id, name: v.product.name, sku: v.variant.sku,
        attrLabel: v.variant.attrLabel, qty: 1, price: v.variant.price, cost: v.variant.costAvg || 0,
        maxQty: v.qty,
      }];
    });
  }
  function addQuickItem() {
    const price = Number(quickPrice);
    if (!quickName.trim()) { showToast("⚠ اكتب اسم الصنف", "err"); return; }
    if (!price || price <= 0) { showToast("⚠ سعر البيع غير صحيح", "err"); return; }
    const costEntered = role !== "employee" && quickCost !== "" ? Number(quickCost) : null;
    setCart((prev) => [...prev, {
      lineId: uid(), variantId: null, name: quickName.trim(), sku: "", attrLabel: "",
      qty: 1, price, cost: costEntered ?? 0, costPending: costEntered == null,
      isQuickItem: true, maxQty: 999999,
    }]);
    setQuickName(""); setQuickPrice(""); setQuickCost(""); setQuickAddOpen(false);
  }
  function changeQty(lineId, delta) {
    setCart((prev) => prev
      .map((l) => (l.lineId === lineId ? { ...l, qty: Math.max(0, Math.min(l.qty + delta, l.maxQty)) } : l))
      .filter((l) => l.qty > 0));
  }
  function removeLine(lineId) {
    setCart((prev) => prev.filter((l) => l.lineId !== lineId));
  }

  function completeSale() {
    if (submittingSaleRef.current) return;
    if (!openShift) { showToast("⚠ يجب بدء البيع اليومي أولاً قبل البيع", "err"); return; }
    if (cart.length === 0) { showToast("⚠ الفاتورة فارغة", "err"); return; }
    if (Math.round(paid * 100) < Math.round(total * 100)) {
      showToast("⚠ المبلغ المدفوع أقل من الإجمالي", "err");
      return;
    }
    submittingSaleRef.current = true;
    const invoiceId = uid();
    const ts = nowISO();
    const cleanPhone = customerPhone.trim();
    const cleanName = customerName.trim();
    update((next) => {
      for (const line of cart) {
        if (line.variantId) {
          pushMovement(next, {
            variantId: line.variantId, type: "بيع", qtyChange: -line.qty,
            unitCost: line.cost, ref: "فاتورة بيع",
          });
        }
      }
      if (!next.customers) next.customers = [];
      let customerId = null;
      if (cleanPhone) {
        const existing = next.customers.find((c) => c.phone === cleanPhone);
        if (existing) {
          customerId = existing.id;
          if (cleanName && !existing.name) existing.name = cleanName;
        } else {
          customerId = uid();
          next.customers.push({ id: customerId, name: cleanName, phone: cleanPhone, createdAt: ts });
        }
      }
      next.invoices.push({
        id: invoiceId, ts, shiftId: openShift.id, seller: openShift.sellerName || "",
        customerId, customerName: cleanName, customerPhone: cleanPhone,
        lines: cart.map((l) => ({
          lineId: l.lineId, variantId: l.variantId, name: l.name, sku: l.sku, qty: l.qty, price: l.price,
          cost: l.cost, costPending: !!l.costPending, isQuickItem: !!l.isQuickItem,
        })),
        payments: payments.filter((p) => Number(p.amount) > 0),
        total,
      });
      if (!next.pendingCostItems) next.pendingCostItems = [];
      for (const l of cart) {
        if (l.costPending) {
          next.pendingCostItems.push({
            id: uid(), invoiceId, lineId: l.lineId, name: l.name, qty: l.qty, price: l.price,
            enteredBy: displayName || "", ts: nowISO(),
          });
        }
      }
    });
    setLastReceipt({
      id: invoiceId, ts, seller: openShift.sellerName || "",
      customerName: cleanName, customerPhone: cleanPhone,
      lines: cart.map((l) => ({ name: l.name, attrLabel: l.attrLabel, qty: l.qty, price: l.price })),
      total,
    });
    setCart([]);
    setPayments([{ method: "كاش", amount: 0 }]);
    setCustomerName(""); setCustomerPhone("");
    showToast("✔ تم إتمام البيع بنجاح");
    setTimeout(() => { submittingSaleRef.current = false; }, 700);
  }

  function holdInvoice() {
    if (cart.length === 0) return;
    update((next) => { next.heldInvoices.push({ id: uid(), ts: nowISO(), cart }); });
    setCart([]);
    showToast("تم تعليق الفاتورة");
  }
  function resumeInvoice(held) {
    setCart(held.cart);
    update((next) => { next.heldInvoices = next.heldInvoices.filter((h) => h.id !== held.id); });
  }

  return (
    <>
    <div className="rb-grid" style={{ display: "grid", gridTemplateColumns: "1fr 380px", gap: 18 }}>
      {/* منتجات */}
      <Panel>
        <div style={{ display: "flex", gap: 10, padding: 16, borderBottom: `1px solid ${C.line}` }}>
          <div style={{ flex: 1, minWidth: 0, display: "flex", alignItems: "center", gap: 8, background: C.cream, border: `1.5px solid ${C.line}`, borderRadius: 12, padding: "9px 14px" }}>
            <Search size={18} color={C.muted} />
            <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="ابحث بالاسم أو الـ SKU..."
              style={{ border: "none", outline: "none", background: "transparent", flex: 1, fontSize: 15.5 }} />
          </div>
          {db.heldInvoices.length > 0 && (
            <div style={{ display: "flex", gap: 6, alignItems: "center" }}>
              <ClipboardList size={18} color={C.amber} />
              {db.heldInvoices.map((h) => (
                <button key={h.id} onClick={() => resumeInvoice(h)} style={{
                  fontSize: 13, background: "#FDF2E3", color: C.amber, border: "none", borderRadius: 8, padding: "6px 10px", fontWeight: 700, cursor: "pointer",
                }}>استئناف {fmtDate(h.ts).split(" ")[1]}</button>
              ))}
            </div>
          )}
          <button onClick={() => setQuickAddOpen((v) => !v)} style={{
            fontSize: 13, background: quickAddOpen ? C.plum : "#F3ECEF", color: quickAddOpen ? "#fff" : C.plum,
            border: "none", borderRadius: 8, padding: "9px 12px", fontWeight: 700, cursor: "pointer", whiteSpace: "nowrap",
          }}>+ صنف غير موجود</button>
        </div>
        {quickAddOpen && (
          <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "flex-end", padding: "12px 16px", background: C.cream, borderBottom: `1px solid ${C.line}` }}>
            <div style={{ flex: "1 1 160px" }}>
              <div style={{ fontSize: 13, color: C.muted, marginBottom: 4 }}>اسم الصنف</div>
              <input value={quickName} onChange={(e) => setQuickName(e.target.value)}
                style={{ width: "100%", boxSizing: "border-box", padding: "8px 10px", borderRadius: 8, border: `1px solid ${C.line}`, fontFamily: "inherit" }} />
            </div>
            <div style={{ flex: "1 1 100px" }}>
              <div style={{ fontSize: 13, color: C.muted, marginBottom: 4 }}>سعر البيع</div>
              <input type="number" value={quickPrice} onChange={(e) => setQuickPrice(e.target.value)}
                style={{ width: "100%", boxSizing: "border-box", padding: "8px 10px", borderRadius: 8, border: `1px solid ${C.line}`, fontFamily: "inherit" }} />
            </div>
            {role !== "employee" && (
              <div style={{ flex: "1 1 100px" }}>
                <div style={{ fontSize: 13, color: C.muted, marginBottom: 4 }}>سعر التكلفة (اختياري)</div>
                <input type="number" value={quickCost} onChange={(e) => setQuickCost(e.target.value)}
                  style={{ width: "100%", boxSizing: "border-box", padding: "8px 10px", borderRadius: 8, border: `1px solid ${C.line}`, fontFamily: "inherit" }} />
              </div>
            )}
            <button onClick={addQuickItem} style={{
              background: C.gold, color: C.plumDeep, border: "none", borderRadius: 8, padding: "9px 16px", fontWeight: 800, cursor: "pointer",
            }}>إضافة للفاتورة</button>
            {role === "employee" && (
              <div style={{ flexBasis: "100%", fontSize: 13, color: C.muted }}>سيُطلب من المدير إكمال سعر التكلفة لهذا الصنف لاحقًا.</div>
            )}
          </div>
        )}
        <div className="rb-grid-cards" style={{ display: "grid", gridTemplateColumns: "repeat(4,1fr)", gap: 12, padding: 16, minHeight: 240 }}>
          {filtered.length === 0 && (
            <div style={{ gridColumn: "span 4", textAlign: "center", color: C.muted, padding: 30, fontSize: 14.5 }}>
              لا توجد منتجات — أضيفوا منتجات من تبويب "المنتجات" أولاً
            </div>
          )}
          {filtered.map((v) => (
            <div key={v.variant.id} onClick={() => addToCart(v)} style={{
              border: `1px solid ${C.line}`, borderRadius: 14, padding: 12, cursor: "pointer", background: "#fff",
            }}>
              <div style={{ height: 54, borderRadius: 10, marginBottom: 8, background: `linear-gradient(135deg,#F3E9DA,#E8D3B0)`, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 20.5 }}>📦</div>
              <div style={{ fontSize: 14, fontWeight: 700, marginBottom: 3, lineHeight: 1.3 }}>{v.product.name}{v.variant.attrLabel ? ` — ${v.variant.attrLabel}` : ""}</div>
              <div style={{ fontSize: 13, color: C.muted, display: "flex", justifyContent: "space-between" }}>
                <span style={{ color: v.qty <= (v.variant.minStock || 3) ? C.amber : C.muted, fontWeight: v.qty <= (v.variant.minStock || 3) ? 700 : 400 }}>
                  متاح: {v.qty}
                </span>
                <span style={{ fontFamily: "Tahoma", fontWeight: 800, color: C.plum }}>{fmtMoney(v.variant.price)} ج.م</span>
              </div>
            </div>
          ))}
        </div>
      </Panel>

      {/* السلة */}
      <Panel>
        <div style={{ padding: 16, borderBottom: `1px solid ${C.line}`, fontWeight: 800, fontSize: 16 }}>الفاتورة الحالية</div>
        <div style={{ padding: "8px 16px", maxHeight: 260, overflow: "auto" }}>
          {cart.length === 0 && <div style={{ color: C.muted, fontSize: 14, padding: "20px 0", textAlign: "center" }}>السلة فارغة — اضغط على منتج لإضافته</div>}
          {cart.map((l) => (
            <div key={l.lineId} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "10px 0", borderBottom: `1px solid ${C.line}`, gap: 8 }}>
              <div style={{ flex: 1 }}>
                <div style={{ fontSize: 14, fontWeight: 700 }}>{l.name}{l.attrLabel ? ` — ${l.attrLabel}` : ""}
                  {l.costPending && <span style={{ marginInlineStart: 6, fontSize: 12, fontWeight: 800, color: C.amber, background: "#FCF1DC", padding: "1px 6px", borderRadius: 6 }}>بانتظار سعر التكلفة</span>}
                </div>
                <div style={{ fontSize: 12.5, color: C.muted }}>{l.sku}</div>
              </div>
              <div style={{ display: "flex", alignItems: "center", gap: 6, background: C.cream, borderRadius: 8, padding: 3 }}>
                <button onClick={() => changeQty(l.lineId, -1)} style={btnMini}><Minus size={14} /></button>
                <span style={{ fontSize: 13.5, fontWeight: 700, minWidth: 14, textAlign: "center" }}>{l.qty}</span>
                <button onClick={() => changeQty(l.lineId, 1)} style={btnMini}><Plus size={14} /></button>
              </div>
              <div style={{ fontWeight: 700, fontSize: 14, minWidth: 60, textAlign: "left" }}>{fmtMoney(l.qty * l.price)}</div>
              <button onClick={() => removeLine(l.lineId)} style={{ border: "none", background: "transparent", color: C.red, cursor: "pointer" }}><X size={16} /></button>
            </div>
          ))}
        </div>

        <div style={{ padding: "12px 16px", background: C.cream, marginTop: 8 }}>
          <div style={{ display: "flex", justifyContent: "space-between", fontSize: 18, fontWeight: 800, marginBottom: 10 }}>
            <span>الإجمالي</span><span>{fmtMoney(total)} ج.م</span>
          </div>
          {payments.map((p, i) => (
            <div key={i} style={{ display: "flex", gap: 6, marginBottom: 6 }}>
              <select value={p.method} onChange={(e) => setPayments((prev) => prev.map((x, xi) => xi === i ? { ...x, method: e.target.value } : x))}
                style={{ flex: 1, padding: "7px 8px", borderRadius: 8, border: `1.5px solid ${C.line}`, fontSize: 13.5 }}>
                {PAYMENT_METHODS.map((m) => <option key={m} value={m}>{m}</option>)}
              </select>
              <input type="number" value={p.amount} onChange={(e) => setPayments((prev) => prev.map((x, xi) => xi === i ? { ...x, amount: e.target.value } : x))}
                placeholder="المبلغ" style={{ width: 90, padding: "7px 8px", borderRadius: 8, border: `1.5px solid ${C.line}`, fontSize: 13.5 }} />
              {payments.length > 1 && (
                <button onClick={() => setPayments((prev) => prev.filter((_, xi) => xi !== i))} style={{ border: "none", background: "transparent", color: C.red, cursor: "pointer" }}><X size={16} /></button>
              )}
            </div>
          ))}
          <button onClick={() => setPayments((prev) => [...prev, { method: "كاش", amount: 0 }])}
            style={{ fontSize: 13, color: C.plum, background: "transparent", border: "none", cursor: "pointer", fontWeight: 700, marginBottom: 8 }}>+ إضافة طريقة دفع أخرى</button>
          <div style={{ marginBottom: 10, position: "relative" }}>
            <div style={{ fontSize: 12, color: C.muted, marginBottom: 4 }}>بيانات الزبون (اختياري)</div>
            <div style={{ display: "flex", gap: 6 }}>
              <input placeholder="رقم الجوال" value={customerPhone} onChange={(e) => setCustomerPhone(e.target.value)}
                style={{ flex: 1, boxSizing: "border-box", padding: "8px 10px", borderRadius: 8, border: `1px solid ${C.line}`, fontFamily: "inherit", fontSize: 13 }} />
              <input placeholder="الاسم" value={customerName} onChange={(e) => setCustomerName(e.target.value)}
                style={{ flex: 1, boxSizing: "border-box", padding: "8px 10px", borderRadius: 8, border: `1px solid ${C.line}`, fontFamily: "inherit", fontSize: 13 }} />
            </div>
            {customerSuggestions.length > 0 && (
              <div style={{ position: "absolute", top: "100%", insetInlineStart: 0, insetInlineEnd: 0, background: "#fff", border: `1px solid ${C.line}`, borderRadius: 8, boxShadow: "0 6px 16px rgba(0,0,0,.1)", zIndex: 5, marginTop: 2 }}>
                {customerSuggestions.map((c) => (
                  <div key={c.id} onClick={() => { setCustomerPhone(c.phone); setCustomerName(c.name); }}
                    style={{ padding: "8px 10px", fontSize: 12.5, cursor: "pointer", borderBottom: `1px solid ${C.line}` }}>
                    {c.name || "بدون اسم"} — {c.phone}
                  </div>
                ))}
              </div>
            )}
          </div>
          <div style={{ fontSize: 13, color: paid < total ? C.red : C.green, fontWeight: 700, marginBottom: 10 }}>
            المدفوع: {fmtMoney(paid)} ج.م {paid < total ? `— متبقي ${fmtMoney(total - paid)}` : "✔"}
          </div>
          <button onClick={completeSale} disabled={!openShift} style={{
            width: "100%", padding: 14, border: "none", borderRadius: 12, cursor: openShift ? "pointer" : "not-allowed",
            background: openShift ? `linear-gradient(135deg,${C.plum},${C.plumDeep})` : C.line, color: openShift ? "#fff" : C.muted,
            fontWeight: 800, fontSize: 15.5, marginBottom: 8,
          }}>
            {openShift ? `إتمام البيع — ${fmtMoney(total)} ج.م` : "ابدأ البيع اليومي أولاً"}
          </button>
          <button onClick={holdInvoice} style={{ width: "100%", padding: 9, borderRadius: 10, border: `1.5px solid ${C.line}`, background: "#fff", color: C.muted, fontWeight: 700, fontSize: 13.5, cursor: "pointer" }}>
            تعليق الفاتورة
          </button>
        </div>
      </Panel>
    </div>
    {lastReceipt && <ReceiptModal receipt={lastReceipt} onClose={() => setLastReceipt(null)} />}
    </>
  );
}
const btnMini = { width: 20, height: 20, border: "none", background: "#fff", borderRadius: 5, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", color: C.plum };

/* ============================================================
   المنتجات — إضافة / قائمة / استيراد سريع
============================================================ */
function PendingCostBanner({ db, update, showToast }) {
  const pending = db.pendingCostItems || [];
  const [drafts, setDrafts] = useState({});
  if (pending.length === 0) return null;

  function saveCost(item) {
    const cost = Number(drafts[item.id]);
    if (!cost || cost <= 0) { showToast("⚠ اكتب سعر تكلفة صحيح", "err"); return; }
    update((next) => {
      const inv = next.invoices.find((i) => i.id === item.invoiceId);
      if (inv) {
        const line = inv.lines.find((l) => l.lineId === item.lineId);
        if (line) { line.cost = cost; line.costPending = false; }
      }
      next.pendingCostItems = (next.pendingCostItems || []).filter((p) => p.id !== item.id);
    });
    showToast("✔ تم حفظ سعر التكلفة");
  }

  return (
    <div style={{ background: "#FCF1DC", border: "1.5px solid #F0DFC0", borderRadius: 12, padding: 16, marginBottom: 16 }}>
      <div style={{ fontWeight: 800, fontSize: 15, color: "#8A6420", marginBottom: 10 }}>
        ⚠ أصناف باعها الموظفون بدون سعر تكلفة — أكمل السعر عشان تنضبط الأرباح ({pending.length})
      </div>
      {pending.map((item) => (
        <div key={item.id} style={{ display: "flex", gap: 10, alignItems: "center", padding: "8px 0", borderTop: "1px solid #F0DFC0", flexWrap: "wrap" }}>
          <div style={{ flex: "1 1 160px", fontSize: 14, fontWeight: 700 }}>{item.name}</div>
          <div style={{ fontSize: 13, color: "#8A6420" }}>الكمية: {item.qty} — سعر البيع: {fmtMoney(item.price)}</div>
          <div style={{ fontSize: 13, color: "#8A6420" }}>باعها: {item.enteredBy} — {fmtDate(item.ts)}</div>
          <input type="number" placeholder="سعر التكلفة" value={drafts[item.id] || ""} onChange={(e) => setDrafts({ ...drafts, [item.id]: e.target.value })}
            style={{ width: 110, padding: "6px 10px", borderRadius: 8, border: "1px solid #E5CE9E", fontFamily: "inherit" }} />
          <button onClick={() => saveCost(item)} style={{ background: C.plum, color: "#fff", border: "none", borderRadius: 8, padding: "7px 14px", fontWeight: 700, cursor: "pointer" }}>
            حفظ
          </button>
        </div>
      ))}
    </div>
  );
}

function ProductsView({ db, update, showToast }) {
  const [subTab, setSubTab] = useState("list");
  return (
    <div>
      <PendingCostBanner db={db} update={update} showToast={showToast} />
      <div style={{ display: "flex", gap: 8, marginBottom: 16 }}>
        {[["list", "قائمة المنتجات"], ["add", "إضافة منتج"], ["bulk", "استيراد سريع"]].map(([id, label]) => (
          <button key={id} onClick={() => setSubTab(id)} style={{
            padding: "8px 16px", borderRadius: 10, border: `1.5px solid ${subTab === id ? C.plum : C.line}`,
            background: subTab === id ? C.plum : "#fff", color: subTab === id ? "#fff" : C.muted, fontWeight: 700, fontSize: 14.5, cursor: "pointer",
          }}>{label}</button>
        ))}
      </div>
      {subTab === "list" && <ProductList db={db} update={update} showToast={showToast} />}
      {subTab === "add" && <AddProduct db={db} update={update} showToast={showToast} />}
      {subTab === "bulk" && <BulkImport db={db} update={update} showToast={showToast} />}
    </div>
  );
}

function ProductList({ db, update, showToast }) {
  const [q, setQ] = useState("");
  const [editing, setEditing] = useState(null); // {productId, variantId}
  const rows = useMemo(() => {
    const list = allVariants(db);
    const query = q.trim().toLowerCase();
    return query ? list.filter((r) => r.product.name.toLowerCase().includes(query) || r.variant.sku.toLowerCase().includes(query)) : list;
  }, [db, q]);

  return (
    <Panel>
      <div style={{ padding: 16, borderBottom: `1px solid ${C.line}` }}>
        <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="بحث بالاسم أو SKU..."
          style={{ width: "100%", padding: "9px 14px", borderRadius: 10, border: `1.5px solid ${C.line}`, fontSize: 14.5 }} />
      </div>
      <div className="rb-table-wrap" style={{ overflow: "auto" }}>
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 14 }}>
          <thead>
            <tr style={{ background: C.cream }}>
              {["المنتج", "المتغير", "SKU", "الفئة", "السعر", "متوسط التكلفة", "الرصيد الحالي", ""].map((h) => (
                <th key={h} style={{ padding: "9px 10px", textAlign: "right", color: C.muted, fontSize: 13, borderBottom: `1.5px solid ${C.line}` }}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {rows.length === 0 && <tr><td colSpan={8}><EmptyState icon={Package} text="لا توجد منتجات بعد" /></td></tr>}
            {rows.map((r) => (
              <tr key={r.variant.id} style={{ borderBottom: `1px solid ${C.line}` }}>
                <td style={{ padding: "8px 10px", fontWeight: 700 }}>{r.product.name}</td>
                <td style={{ padding: "8px 10px", color: C.muted }}>{r.variant.attrLabel || "—"}</td>
                <td style={{ padding: "8px 10px", fontFamily: "monospace" }}>{r.variant.sku}</td>
                <td style={{ padding: "8px 10px" }}>{r.product.category}</td>
                <td style={{ padding: "8px 10px", fontWeight: 700 }}>{fmtMoney(r.variant.price)}</td>
                <td style={{ padding: "8px 10px", color: C.muted }}>{fmtMoney(r.variant.costAvg || 0)}</td>
                <td style={{ padding: "8px 10px", fontWeight: 800, color: r.qty <= (r.variant.minStock || 3) ? C.amber : C.green }}>{r.qty}</td>
                <td style={{ padding: "8px 10px" }}>
                  <button onClick={() => setEditing({ productId: r.product.id, variantId: r.variant.id })} title="تعديل"
                    style={{ border: "none", background: "transparent", color: C.plum, cursor: "pointer", padding: 4 }}>
                    <Edit2 size={16} />
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {editing && (
        <EditVariantModal
          db={db} update={update} showToast={showToast}
          productId={editing.productId} variantId={editing.variantId}
          onClose={() => setEditing(null)}
        />
      )}
    </Panel>
  );
}

function EditVariantModal({ db, update, showToast, productId, variantId, onClose }) {
  const product = db.products.find((p) => p.id === productId);
  const variant = product?.variants.find((v) => v.id === variantId);
  const [name, setName] = useState(product?.name || "");
  const [category, setCategory] = useState(product?.category || "");
  const [attrLabel, setAttrLabel] = useState(variant?.attrLabel || "");
  const [sku, setSku] = useState(variant?.sku || "");
  const [barcode, setBarcode] = useState(variant?.barcode || "");
  const [price, setPrice] = useState(variant?.price ?? "");
  const [minPrice, setMinPrice] = useState(variant?.minPrice ?? "");
  const [costAvg, setCostAvg] = useState(variant?.costAvg ?? "");
  const [minStock, setMinStock] = useState(variant?.minStock ?? "");

  if (!product || !variant) return null;

  function save() {
    if (!name.trim()) { showToast("⚠ اسم المنتج مطلوب", "err"); return; }
    if (!price || Number(price) <= 0) { showToast("⚠ السعر غير صحيح", "err"); return; }
    update((next) => {
      const p = next.products.find((p) => p.id === productId);
      if (!p) return;
      p.name = name.trim();
      p.category = category;
      const v = p.variants.find((v) => v.id === variantId);
      if (v) {
        v.attrLabel = attrLabel.trim();
        v.sku = sku.trim();
        v.barcode = barcode.trim();
        v.price = Number(price);
        v.minPrice = minPrice === "" ? null : Number(minPrice);
        v.costAvg = costAvg === "" ? 0 : Number(costAvg);
        v.minStock = minStock === "" ? 3 : Number(minStock);
      }
    });
    showToast("✔ تم حفظ التعديلات");
    onClose();
  }

  return (
    <div className="no-print" style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,.45)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 100, padding: 16 }}>
      <div style={{ background: "#fff", borderRadius: 16, padding: 24, width: "min(440px,94vw)", maxHeight: "88vh", overflow: "auto", boxShadow: "0 20px 50px rgba(0,0,0,.25)" }}>
        <div style={{ fontWeight: 800, fontSize: 16.5, marginBottom: 16, color: C.plumDeep }}>تعديل المنتج</div>
        <Field label="اسم المنتج"><input value={name} onChange={(e) => setName(e.target.value)} style={inputStyle} /></Field>
        <div style={{ height: 10 }} />
        <Field label="الفئة">
          <select value={category} onChange={(e) => setCategory(e.target.value)} style={inputStyle}>
            {db.categories.map((c) => <option key={c}>{c}</option>)}
          </select>
        </Field>
        <div style={{ height: 10 }} />
        {product.hasVariants && (
          <>
            <Field label="اسم المتغيّر (مثل: أحمر / كبير)"><input value={attrLabel} onChange={(e) => setAttrLabel(e.target.value)} style={inputStyle} /></Field>
            <div style={{ height: 10 }} />
          </>
        )}
        <div className="rb-grid" style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
          <Field label="SKU"><input value={sku} onChange={(e) => setSku(e.target.value)} style={inputStyle} /></Field>
          <Field label="الباركود"><input value={barcode} onChange={(e) => setBarcode(e.target.value)} style={inputStyle} /></Field>
        </div>
        <div style={{ height: 10 }} />
        <div className="rb-grid" style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
          <Field label="سعر البيع"><input type="number" value={price} onChange={(e) => setPrice(e.target.value)} style={inputStyle} /></Field>
          <Field label="أقل سعر بيع مسموح"><input type="number" value={minPrice} onChange={(e) => setMinPrice(e.target.value)} style={inputStyle} /></Field>
        </div>
        <div style={{ height: 10 }} />
        <div className="rb-grid" style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
          <Field label="متوسط سعر التكلفة"><input type="number" value={costAvg} onChange={(e) => setCostAvg(e.target.value)} style={inputStyle} /></Field>
          <Field label="حد التنبيه لانخفاض المخزون"><input type="number" value={minStock} onChange={(e) => setMinStock(e.target.value)} style={inputStyle} /></Field>
        </div>
        <div style={{ display: "flex", gap: 8, marginTop: 18 }}>
          <button onClick={save} style={{ ...smallBtnFilled, flex: 1, padding: 12 }}>حفظ التعديلات</button>
          <button onClick={onClose} style={{ ...smallBtnOutline, flex: 1, padding: 12 }}>إلغاء</button>
        </div>
      </div>
    </div>
  );
}

function AddProduct({ db, update, showToast }) {
  const [name, setName] = useState("");
  const [category, setCategory] = useState(db.categories[0] || "");
  const [hasVariants, setHasVariants] = useState(false);
  const [price, setPrice] = useState("");
  const [minPrice, setMinPrice] = useState("");
  const [minStock, setMinStock] = useState(3);
  const [openingQty, setOpeningQty] = useState(0);
  const [attrTypes, setAttrTypes] = useState([{ name: "اللون", values: "" }]);
  const [generated, setGenerated] = useState([]);

  function addAttrType() { setAttrTypes((prev) => [...prev, { name: "", values: "" }]); }
  function genVariants() {
    const lists = attrTypes
      .filter((a) => a.name.trim() && a.values.trim())
      .map((a) => ({ name: a.name.trim(), values: a.values.split(",").map((v) => v.trim()).filter(Boolean) }));
    if (lists.length === 0) { showToast("⚠ أدخل خاصية واحدة على الأقل بقيمها", "err"); return; }
    let combos = [{}];
    for (const l of lists) {
      const next = [];
      for (const c of combos) for (const v of l.values) next.push({ ...c, [l.name]: v });
      combos = next;
    }
    setGenerated(combos.map((c) => ({
      id: uid(), attrs: c, label: Object.values(c).join(" · "),
      price: price || 0, minPrice: minPrice || 0, qty: 0,
    })));
  }

  function save() {
    if (!name.trim()) { showToast("⚠ اسم المنتج مطلوب", "err"); return; }
    if (!hasVariants && (!price || Number(price) <= 0)) { showToast("⚠ السعر مطلوب", "err"); return; }
    if (hasVariants && generated.length === 0) { showToast("⚠ ولّد المتغيرات أولاً", "err"); return; }

    update((next) => {
      const seqKey = category;
      const seq = (next.categorySeq[seqKey] || 0) + 1;
      next.categorySeq[seqKey] = seq;
      const baseSku = `${shortPrefix(category)}-${String(seq).padStart(5, "0")}`;
      const productId = uid();

      let variants = [];
      if (!hasVariants) {
        variants = [{
          id: uid(), sku: baseSku, barcode: baseSku, attrLabel: "",
          price: Number(price), minPrice: Number(minPrice) || Number(price),
          costAvg: 0, minStock: Number(minStock) || 3,
        }];
      } else {
        variants = generated.map((g, i) => ({
          id: g.id, sku: `${baseSku}-${i + 1}`, barcode: `${baseSku}-${i + 1}`, attrLabel: g.label,
          price: Number(g.price) || Number(price) || 0, minPrice: Number(g.minPrice) || Number(minPrice) || 0,
          costAvg: 0, minStock: Number(minStock) || 3,
        }));
      }

      next.products.push({ id: productId, name: name.trim(), category, hasVariants, variants });

      const totalOpeningQty = hasVariants ? generated.reduce((s, g) => s + (Number(g.qty) || 0), 0) : Number(openingQty) || 0;
      if (!hasVariants && Number(openingQty) > 0) {
        pushMovement(next, { variantId: variants[0].id, type: "رصيد افتتاحي", qtyChange: Number(openingQty), unitCost: 0, ref: "إضافة منتج" });
      }
      if (hasVariants) {
        generated.forEach((g, i) => {
          if (Number(g.qty) > 0) pushMovement(next, { variantId: variants[i].id, type: "رصيد افتتاحي", qtyChange: Number(g.qty), unitCost: 0, ref: "إضافة منتج" });
        });
      }
    });

    showToast("✔ تم حفظ المنتج وتوليد SKU تلقائيًا");
    setName(""); setPrice(""); setMinPrice(""); setOpeningQty(0); setGenerated([]); setHasVariants(false);
  }

  return (
    <Panel>
      <div className="rb-grid" style={{ padding: 18, display: "grid", gridTemplateColumns: "repeat(3,1fr)", gap: 14 }}>
        <Field label="اسم المنتج"><input value={name} onChange={(e) => setName(e.target.value)} style={inputStyle} /></Field>
        <Field label="الفئة">
          <select value={category} onChange={(e) => setCategory(e.target.value)} style={inputStyle}>
            {db.categories.map((c) => <option key={c} value={c}>{c}</option>)}
          </select>
        </Field>
        <Field label="الحد الأدنى للمخزون (تنبيه)"><input type="number" value={minStock} onChange={(e) => setMinStock(e.target.value)} style={inputStyle} /></Field>

        <div style={{ gridColumn: "span 3", display: "flex", alignItems: "center", gap: 8 }}>
          <input type="checkbox" checked={hasVariants} onChange={(e) => { setHasVariants(e.target.checked); setGenerated([]); }} id="hv" />
          <label htmlFor="hv" style={{ fontSize: 14.5, fontWeight: 700 }}>هذا المنتج له متغيرات (لون/مقاس/خامة...)</label>
        </div>

        {!hasVariants && (
          <>
            <Field label="سعر البيع"><input type="number" value={price} onChange={(e) => setPrice(e.target.value)} style={inputStyle} /></Field>
            <Field label="الحد الأدنى للبيع (اختياري)"><input type="number" value={minPrice} onChange={(e) => setMinPrice(e.target.value)} style={inputStyle} /></Field>
            <Field label="رصيد افتتاحي"><input type="number" value={openingQty} onChange={(e) => setOpeningQty(e.target.value)} style={inputStyle} /></Field>
          </>
        )}
      </div>

      {hasVariants && (
        <div style={{ padding: "0 18px 18px" }}>
          <div style={{ fontSize: 14, fontWeight: 700, color: C.plum, marginBottom: 8 }}>الخصائص (اكتب القيم مفصولة بفاصلة)</div>
          {attrTypes.map((a, i) => (
            <div key={i} style={{ display: "flex", gap: 8, marginBottom: 8 }}>
              <input placeholder="اسم الخاصية (مثال: اللون)" value={a.name} onChange={(e) => setAttrTypes((p) => p.map((x, xi) => xi === i ? { ...x, name: e.target.value } : x))} style={{ ...inputStyle, width: 160 }} />
              <input placeholder="القيم: أسود,أبيض,أحمر" value={a.values} onChange={(e) => setAttrTypes((p) => p.map((x, xi) => xi === i ? { ...x, values: e.target.value } : x))} style={{ ...inputStyle, flex: 1 }} />
            </div>
          ))}
          <div style={{ display: "flex", gap: 10, marginBottom: 14 }}>
            <button onClick={addAttrType} style={smallBtnOutline}>+ خاصية أخرى</button>
            <button onClick={genVariants} style={smallBtnFilled}>توليد المتغيرات</button>
          </div>

          {generated.length > 0 && (
            <div className="rb-table-wrap"><table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13.5 }}>
              <thead><tr style={{ background: C.cream }}>
                <th style={thStyle}>المتغيّر</th><th style={thStyle}>السعر</th><th style={thStyle}>الحد الأدنى</th><th style={thStyle}>رصيد افتتاحي</th>
              </tr></thead>
              <tbody>
                {generated.map((g, i) => (
                  <tr key={g.id} style={{ borderBottom: `1px solid ${C.line}` }}>
                    <td style={tdStyle}>{g.label}</td>
                    <td style={tdStyle}><input type="number" value={g.price} onChange={(e) => setGenerated((p) => p.map((x, xi) => xi === i ? { ...x, price: e.target.value } : x))} style={{ ...inputStyle, width: 80 }} /></td>
                    <td style={tdStyle}><input type="number" value={g.minPrice} onChange={(e) => setGenerated((p) => p.map((x, xi) => xi === i ? { ...x, minPrice: e.target.value } : x))} style={{ ...inputStyle, width: 80 }} /></td>
                    <td style={tdStyle}><input type="number" value={g.qty} onChange={(e) => setGenerated((p) => p.map((x, xi) => xi === i ? { ...x, qty: e.target.value } : x))} style={{ ...inputStyle, width: 80 }} /></td>
                  </tr>
                ))}
              </tbody>
            </table></div>
          )}
        </div>
      )}

      <div style={{ padding: 18, borderTop: `1px solid ${C.line}` }}>
        <button onClick={save} style={{ ...smallBtnFilled, padding: "12px 30px", fontSize: 15.5 }}>حفظ المنتج</button>
      </div>
    </Panel>
  );
}

function BulkImport({ db, update, showToast }) {
  const [text, setText] = useState("");
  const [category, setCategory] = useState(db.categories[0] || "");
  const [rows, setRows] = useState([]);

  async function handleFile(e) {
    const file = e.target.files[0];
    e.target.value = "";
    if (!file) return;
    try {
      const buf = await file.arrayBuffer();
      const wb = XLSX.read(buf, { type: "array" });
      const ws = wb.Sheets[wb.SheetNames[0]];
      let data = XLSX.utils.sheet_to_json(ws, { header: 1 });
      data = data.filter((row) => row.some((cell) => cell !== undefined && cell !== ""));
      if (data.length && (isNaN(Number(data[0][1])) || isNaN(Number(data[0][2])))) {
        data = data.slice(1);
      }
      const lines = data.map((row) => `${row[0] ?? ""},${row[1] ?? ""},${row[2] ?? ""}`).join("\n");
      setText(lines);
      showToast(`✔ تم قراءة ${data.length} صف من الملف — اضغط "معاينة" للتأكد`);
    } catch (err) {
      showToast("⚠ تعذّرت قراءة الملف — تأكد إنه Excel صحيح (xlsx/xls/csv)", "err");
    }
  }
  function parse() {
    const lines = text.split("\n").map((l) => l.trim()).filter(Boolean);
    const seen = {};
    const parsed = lines.map((line, idx) => {
      const parts = line.split(",").map((p) => p.trim());
      const name = parts[0] || "";
      const price = Number(parts[1]);
      const qty = Number(parts[2]);
      let status = "ok", note = "جاهز";
      if (!name) { status = "err"; note = "الاسم مفقود"; }
      else if (!parts[1] || isNaN(price) || price <= 0) { status = "err"; note = "السعر غير صالح"; }
      else if (!parts[2] || isNaN(qty) || qty < 0) { status = "err"; note = "الكمية غير صالحة"; }
      else if (seen[name.toLowerCase()]) { status = "warn"; note = "يشبه سطرًا آخر — تكرار محتمل"; }
      if (status === "ok") seen[name.toLowerCase()] = true;
      return { idx, name, price, qty, status, note };
    });
    setRows(parsed);
  }

  const validRows = rows.filter((r) => r.status !== "err");

  function commit() {
    if (validRows.length === 0) { showToast("⚠ لا توجد أسطر صالحة للاستيراد", "err"); return; }
    update((next) => {
      const seqKey = category;
      for (const r of validRows) {
        let seq = (next.categorySeq[seqKey] || 0) + 1;
        next.categorySeq[seqKey] = seq;
        const sku = `${shortPrefix(category)}-${String(seq).padStart(5, "0")}`;
        const variant = { id: uid(), sku, barcode: sku, attrLabel: "", price: r.price, minPrice: r.price, costAvg: 0, minStock: 3 };
        next.products.push({ id: uid(), name: r.name, category, hasVariants: false, variants: [variant] });
        if (r.qty > 0) pushMovement(next, { variantId: variant.id, type: "رصيد افتتاحي", qtyChange: r.qty, unitCost: 0, ref: "استيراد سريع" });
      }
    });
    showToast(`✔ تم استيراد ${validRows.length} منتج بنجاح`);
    setText(""); setRows([]);
  }

  return (
    <Panel>
      <div className="rb-grid" style={{ padding: 18, display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16 }}>
        <div>
          <div style={{ fontSize: 13.5, fontWeight: 700, color: C.muted, marginBottom: 8 }}>الصق قائمتك: الاسم, السعر, الكمية (سطر لكل منتج) — أو ارفع ملف Excel/CSV مباشرة</div>
          <div style={{ marginBottom: 10 }}>
            <label style={{
              display: "inline-flex", alignItems: "center", gap: 6, padding: "9px 16px", borderRadius: 10,
              border: `1.5px dashed ${C.line}`, background: C.cream, color: C.plum, fontWeight: 700, fontSize: 13.5, cursor: "pointer",
            }}>
              <Upload size={16} /> رفع ملف Excel / CSV
              <input type="file" accept=".xlsx,.xls,.csv" onChange={handleFile} style={{ display: "none" }} />
            </label>
          </div>
          <textarea value={text} onChange={(e) => setText(e.target.value)} placeholder={"خاتم أثر فضة, 180, 5\nسوار لؤلؤ صناعي, 140, 8"}
            style={{ width: "100%", height: 200, border: `1.5px solid ${C.line}`, borderRadius: 12, padding: 14, fontFamily: "monospace", fontSize: 14.5, direction: "ltr", textAlign: "left" }} />
          <div style={{ display: "flex", gap: 10, marginTop: 10, alignItems: "center" }}>
            <span style={{ fontSize: 13.5, fontWeight: 700, color: C.muted }}>الفئة لكل الأسطر:</span>
            <select value={category} onChange={(e) => setCategory(e.target.value)} style={{ ...inputStyle, width: 160 }}>
              {db.categories.map((c) => <option key={c} value={c}>{c}</option>)}
            </select>
            <button onClick={parse} style={smallBtnFilled}>معاينة</button>
          </div>
        </div>
        <div>
          <div style={{ fontSize: 13.5, fontWeight: 700, color: C.muted, marginBottom: 8 }}>معاينة قبل الحفظ — لا يُحفظ شيء تلقائيًا</div>
          {rows.length === 0 ? (
            <div style={{ color: C.muted, fontSize: 14, padding: 20, textAlign: "center", border: `1.5px dashed ${C.line}`, borderRadius: 12 }}>اضغط "معاينة" لرؤية النتيجة</div>
          ) : (
            <div className="rb-table-wrap"><table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13.5 }}>
              <thead><tr style={{ background: C.cream }}><th style={thStyle}>الاسم</th><th style={thStyle}>السعر</th><th style={thStyle}>الكمية</th><th style={thStyle}>الحالة</th></tr></thead>
              <tbody>
                {rows.map((r) => (
                  <tr key={r.idx} style={{ borderBottom: `1px solid ${C.line}` }}>
                    <td style={tdStyle}>{r.name || "—"}</td>
                    <td style={tdStyle}>{isNaN(r.price) ? "—" : r.price}</td>
                    <td style={tdStyle}>{isNaN(r.qty) ? "—" : r.qty}</td>
                    <td style={tdStyle}>
                      <span style={{
                        fontSize: 12, fontWeight: 800, padding: "2px 8px", borderRadius: 6,
                        background: r.status === "ok" ? "#EAF5EE" : r.status === "warn" ? "#FDF2E3" : "#FBEAEA",
                        color: r.status === "ok" ? C.green : r.status === "warn" ? C.amber : C.red,
                      }}>{r.status === "ok" ? "جاهز" : r.status === "warn" ? "⚠ تحقّق" : "✕ خطأ"}</span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table></div>
          )}
        </div>
      </div>
      {rows.length > 0 && (
        <div style={{ margin: "0 18px 18px", padding: 14, background: C.cream, borderRadius: 12, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <div style={{ fontSize: 14, color: C.muted }}>من {rows.length} أسطر: <b style={{ color: C.ink }}>{validRows.length} جاهزة</b> للاستيراد</div>
          <button onClick={commit} style={smallBtnFilled}>تأكيد واستيراد ({validRows.length})</button>
        </div>
      )}
    </Panel>
  );
}

