/* ============================================================
   المخزون — رصيد حالي + كشف حركة الصنف
============================================================ */
function StockView({ db }) {
  const [selected, setSelected] = useState(null);
  const variants = allVariants(db);
  const movements = selected ? db.movements.filter((m) => m.variantId === selected).slice().reverse() : [];

  return (
    <div className="rb-grid" style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16 }}>
      <Panel>
        <div style={{ padding: 16, borderBottom: `1px solid ${C.line}`, fontWeight: 800 }}>الرصيد الحالي — اضغط على صنف لعرض كشف حركته</div>
        <div className="rb-table-wrap" style={{ maxHeight: 520, overflow: "auto" }}>
          <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 14 }}>
            <thead><tr style={{ background: C.cream }}><th style={thStyle}>المنتج</th><th style={thStyle}>SKU</th><th style={thStyle}>الرصيد</th></tr></thead>
            <tbody>
              {variants.map((v) => (
                <tr key={v.variant.id} onClick={() => setSelected(v.variant.id)} style={{ borderBottom: `1px solid ${C.line}`, cursor: "pointer", background: selected === v.variant.id ? C.cream : "transparent" }}>
                  <td style={tdStyle}>{v.product.name}{v.variant.attrLabel ? ` — ${v.variant.attrLabel}` : ""}</td>
                  <td style={{ ...tdStyle, fontFamily: "monospace" }}>{v.variant.sku}</td>
                  <td style={{ ...tdStyle, fontWeight: 800, color: v.qty <= (v.variant.minStock || 3) ? C.amber : C.green }}>{v.qty}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </Panel>
      <Panel>
        <div style={{ padding: 16, borderBottom: `1px solid ${C.line}`, fontWeight: 800 }}>كشف حركة الصنف</div>
        <div style={{ maxHeight: 520, overflow: "auto", padding: selected ? 0 : 20 }}>
          {!selected && <div style={{ color: C.muted, fontSize: 14, textAlign: "center" }}>اختر صنفًا من القائمة لعرض حركاته</div>}
          {selected && movements.length === 0 && <div style={{ color: C.muted, fontSize: 14, textAlign: "center", padding: 20 }}>لا توجد حركات لهذا الصنف</div>}
          {selected && movements.map((m) => (
            <div key={m.id} style={{ padding: "10px 16px", borderBottom: `1px solid ${C.line}`, fontSize: 13.5 }}>
              <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 3 }}>
                <span style={{ fontWeight: 700 }}>{m.type}</span>
                <span style={{ color: C.muted, fontSize: 13 }}>{fmtDate(m.ts)}</span>
              </div>
              <div style={{ color: C.muted }}>
                {m.qtyBefore} {m.qtyChange >= 0 ? "+" : ""}{m.qtyChange} = <b style={{ color: C.ink }}>{m.qtyAfter}</b>
                {m.unitCost != null && m.unitCost > 0 ? ` — تكلفة الوحدة: ${fmtMoney(m.unitCost)}` : ""}
              </div>
            </div>
          ))}
        </div>
      </Panel>
    </div>
  );
}

/* ============================================================
   البيع اليومي (سابقًا: الوردية) — مطابقة الكاش لكل بائع
============================================================ */
function DailySalesView({ db, update, openShift, showToast, displayName }) {
  const [openingCash, setOpeningCash] = useState(0);
  const [sellerName, setSellerName] = useState(displayName || "");
  const [actualCash, setActualCash] = useState(0);
  const [varianceReason, setVarianceReason] = useState("");

  const shiftInvoices = openShift ? db.invoices.filter((i) => i.shiftId === openShift.id) : [];
  const cashSales = shiftInvoices.reduce((s, inv) => s + inv.payments.filter((p) => p.method === "كاش").reduce((s2, p) => s2 + Number(p.amount), 0), 0);
  const shiftCashExpenses = openShift ? db.expenses.filter((e) => e.method === "كاش" && e.ts >= openShift.openedAt).reduce((s, e) => s + Number(e.amount), 0) : 0;
  const shiftCashRefunds = openShift ? db.returns.filter((r) => r.refundMethod === "كاش" && r.ts >= openShift.openedAt).reduce((s, r) => s + r.total, 0) : 0;
  const expectedCash = (openShift?.openingCash || 0) + cashSales - shiftCashExpenses - shiftCashRefunds;
  const variance = Number(actualCash) - expectedCash;

  function open() {
    if (!sellerName.trim()) { showToast("⚠ اكتب اسم البائع أولاً", "err"); return; }
    update((next) => {
      next.shifts.push({ id: uid(), openedAt: nowISO(), openingCash: Number(openingCash), sellerName: sellerName.trim(), status: "open" });
      if (!next.sellers.includes(sellerName.trim())) next.sellers.push(sellerName.trim());
    });
    showToast("✔ تم بدء البيع اليومي");
  }
  function close() {
    if (Math.abs(variance) > 0.01 && !varianceReason.trim()) { showToast("⚠ يجب كتابة سبب الفارق قبل الإغلاق", "err"); return; }
    update((next) => {
      const s = next.shifts.find((s) => s.id === openShift.id);
      s.status = "closed"; s.closedAt = nowISO(); s.actualCash = Number(actualCash); s.expectedCash = expectedCash; s.variance = variance; s.varianceReason = varianceReason;
    });
    showToast("✔ تم إغلاق البيع اليومي");
    setActualCash(0); setVarianceReason(""); setSellerName("");
  }

  if (!openShift) {
    return (
      <Panel>
        <div style={{ padding: 24, maxWidth: 360 }}>
          <div style={{ fontWeight: 800, marginBottom: 14 }}>بدء البيع اليومي</div>
          <Field label="اسم البائع (username)">
            <input list="sellers-list" value={sellerName} onChange={(e) => setSellerName(e.target.value)} placeholder="اكتب اسمك..." style={inputStyle} />
            <datalist id="sellers-list">{db.sellers.map((s) => <option key={s} value={s} />)}</datalist>
          </Field>
          <div style={{ height: 10 }} />
          <Field label="الرصيد الافتتاحي (كاش)"><input type="number" value={openingCash} onChange={(e) => setOpeningCash(e.target.value)} style={inputStyle} /></Field>
          <button onClick={open} style={{ ...smallBtnFilled, marginTop: 14, width: "100%", padding: 12 }}>بدء البيع اليومي</button>
        </div>
      </Panel>
    );
  }

  return (
    <Panel>
      <div style={{ padding: 24, maxWidth: 460 }}>
        <div style={{ fontWeight: 800, marginBottom: 4 }}>البيع اليومي جارٍ — البائع: {openShift.sellerName || "—"}</div>
        <div style={{ fontSize: 14, color: C.muted, marginBottom: 16 }}>بدأ في {fmtDate(openShift.openedAt)} — عدد الفواتير: {shiftInvoices.length}</div>
        <div style={{ background: C.cream, borderRadius: 12, padding: 14, marginBottom: 16, fontSize: 14.5 }}>
          <Row label="الرصيد الافتتاحي" val={fmtMoney(openShift.openingCash)} />
          <Row label="مبيعات كاش اليوم" val={fmtMoney(cashSales)} />
          {shiftCashExpenses > 0 && <Row label="مصروفات كاش اليوم" val={`− ${fmtMoney(shiftCashExpenses)}`} />}
          {shiftCashRefunds > 0 && <Row label="مرتجعات كاش اليوم" val={`− ${fmtMoney(shiftCashRefunds)}`} />}
          <Row label="الرصيد المتوقع" val={fmtMoney(expectedCash)} bold />
        </div>
        <Field label="الرصيد الفعلي في الصندوق الآن"><input type="number" value={actualCash} onChange={(e) => setActualCash(e.target.value)} style={inputStyle} /></Field>
        {Math.abs(variance) > 0.01 && (
          <div style={{ fontSize: 14, fontWeight: 700, color: variance > 0 ? C.green : C.red, margin: "10px 0" }}>
            الفارق: {variance > 0 ? "+" : ""}{fmtMoney(variance)} ج.م
          </div>
        )}
        {Math.abs(variance) > 0.01 && (
          <Field label="سبب الفارق (إلزامي)"><input value={varianceReason} onChange={(e) => setVarianceReason(e.target.value)} style={inputStyle} /></Field>
        )}
        <button onClick={close} style={{ ...smallBtnFilled, marginTop: 14, width: "100%", padding: 12 }}>إغلاق البيع اليومي</button>
      </div>
    </Panel>
  );
}
function Row({ label, val, bold }) {
  return <div style={{ display: "flex", justifyContent: "space-between", padding: "5px 0", fontWeight: bold ? 800 : 400 }}><span style={{ color: C.muted }}>{label}</span><span>{val} ج.م</span></div>;
}

/* ============================================================
   لوحة التحكم
============================================================ */
function DashboardView({ db }) {
  const today = new Date().toDateString();
  const period = currentMonthKey();
  const fin = computeMonthFinancials(db, period);
  const todaySales = db.invoices.filter((i) => new Date(i.ts).toDateString() === today).reduce((s, i) => s + i.total, 0);
  const variants = allVariants(db);
  const lowStock = variants.filter((v) => v.qty <= (v.variant.minStock || 3));
  const stockValue = variants.reduce((s, v) => s + v.qty * (v.variant.costAvg || 0), 0);

  const salesByProduct = {};
  for (const inv of db.invoices) {
    for (const l of inv.lines) {
      salesByProduct[l.name] = salesByProduct[l.name] || { qty: 0, profit: 0 };
      salesByProduct[l.name].qty += l.qty;
      salesByProduct[l.name].profit += (l.price - l.cost) * l.qty;
    }
  }
  const topByProfit = Object.entries(salesByProduct).sort((a, b) => b[1].profit - a[1].profit).slice(0, 5);

  const salesBySeller = {};
  for (const inv of db.invoices) {
    if (monthKey(inv.ts) !== period) continue;
    const name = inv.seller || "بدون اسم";
    salesBySeller[name] = (salesBySeller[name] || 0) + inv.total;
  }
  const sellerRows = Object.entries(salesBySeller).sort((a, b) => b[1] - a[1]);

  return (
    <div>
      <div className="rb-grid" style={{ display: "grid", gridTemplateColumns: "repeat(4,1fr)", gap: 12, marginBottom: 18 }}>
        <KPI label="مبيعات اليوم" val={`${fmtMoney(todaySales)} ج.م`} icon={ShoppingCart} tint={C.plum} />
        <KPI label="صافي مبيعات الشهر" val={`${fmtMoney(fin.netSales)} ج.م`} icon={Receipt} tint={C.gold} />
        <KPI label="صافي ربح الشهر" val={`${fmtMoney(fin.netProfit)} ج.م`} icon={Wallet} tint={C.green} />
        <KPI label="قيمة المخزون بالتكلفة" val={`${fmtMoney(stockValue)} ج.م`} icon={Boxes} tint={C.magenta} />
      </div>
      <div className="rb-grid" style={{ display: "grid", gridTemplateColumns: "1.3fr 1fr", gap: 16 }}>
        <Panel>
          <div style={{ padding: 16, borderBottom: `1px solid ${C.line}`, fontWeight: 800 }}>أفضل 5 منتجات ربحًا</div>
          <div style={{ padding: 16 }}>
            {topByProfit.length === 0 && <EmptyState icon={FileBarChart} text="لا توجد مبيعات بعد لعرض هذا التقرير" />}
            {topByProfit.map(([name, d], i) => (
              <div key={name} style={{ display: "flex", justifyContent: "space-between", padding: "9px 0", borderBottom: `1px solid ${C.line}`, fontSize: 14 }}>
                <span>{i + 1}. {name} <span style={{ color: C.muted }}>(×{d.qty})</span></span>
                <span style={{ fontWeight: 800, color: C.green }}>{fmtMoney(d.profit)} ج.م</span>
              </div>
            ))}
          </div>
        </Panel>
        <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
          <Panel>
            <div style={{ padding: 16, borderBottom: `1px solid ${C.line}`, fontWeight: 800, display: "flex", alignItems: "center", gap: 6 }}>
              <AlertTriangle size={17} color={C.amber} /> منتجات منخفضة المخزون
            </div>
            <div style={{ padding: 16 }}>
              {lowStock.length === 0 && <EmptyState icon={Check} text="لا توجد تنبيهات حاليًا" />}
              {lowStock.map((v) => (
                <div key={v.variant.id} style={{ display: "flex", justifyContent: "space-between", padding: "8px 0", borderBottom: `1px solid ${C.line}`, fontSize: 14 }}>
                  <span>{v.product.name}{v.variant.attrLabel ? ` — ${v.variant.attrLabel}` : ""}</span>
                  <span style={{ fontWeight: 800, color: C.amber }}>متبقي {v.qty}</span>
                </div>
              ))}
            </div>
          </Panel>
          <Panel>
            <div style={{ padding: 16, borderBottom: `1px solid ${C.line}`, fontWeight: 800 }}>المبيعات حسب البائع — هذا الشهر</div>
            <div style={{ padding: 16 }}>
              {sellerRows.length === 0 && <EmptyState icon={Users} text="لا توجد مبيعات هذا الشهر بعد" />}
              {sellerRows.map(([name, total]) => (
                <div key={name} style={{ display: "flex", justifyContent: "space-between", padding: "8px 0", borderBottom: `1px solid ${C.line}`, fontSize: 14 }}>
                  <span style={{ fontWeight: 700 }}>{name}</span>
                  <span style={{ fontWeight: 800 }}>{fmtMoney(total)} ج.م</span>
                </div>
              ))}
            </div>
          </Panel>
        </div>
      </div>
    </div>
  );
}
function EmptyState({ icon: Icon, text }) {
  return (
    <div style={{ textAlign: "center", padding: "26px 10px", color: C.muted }}>
      <div style={{ width: 44, height: 44, borderRadius: 12, background: C.cream, display: "flex", alignItems: "center", justifyContent: "center", margin: "0 auto 10px" }}>
        <Icon size={20} color={C.muted} />
      </div>
      <div style={{ fontSize: 13.5 }}>{text}</div>
    </div>
  );
}

function KPI({ label, val, icon: Icon, tint }) {
  return (
    <div className="rb-panel" style={{ background: "#fff", border: `1px solid ${C.line}`, borderRadius: 14, padding: 16, display: "flex", alignItems: "center", gap: 14, borderInlineStart: `4px solid ${tint}` }}>
      <div style={{ width: 42, height: 42, borderRadius: 12, background: `${tint}1A`, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
        <Icon size={20} color={tint} />
      </div>
      <div style={{ minWidth: 0 }}>
        <div style={{ fontSize: 12.5, color: C.muted, fontWeight: 600, marginBottom: 4 }}>{label}</div>
        <div style={{ fontWeight: 900, fontSize: 19 }}>{val}</div>
      </div>
    </div>
  );
}

/* ============================================================
   المرتجعات والاستبدال
============================================================ */
function ReturnsView({ db, update, showToast }) {
  const [invoiceId, setInvoiceId] = useState("");
  const [qtyMap, setQtyMap] = useState({});
  const [condMap, setCondMap] = useState({});
  const [refundMethod, setRefundMethod] = useState("كاش");

  const invoice = db.invoices.find((i) => i.id === invoiceId);
  const recentInvoices = [...db.invoices].reverse().slice(0, 30);

  function lineRemaining(l) {
    return l.qty - alreadyReturnedQty(db, invoiceId, l.variantId);
  }

  function submit() {
    if (!invoice) { showToast("⚠ اختر فاتورة أولاً", "err"); return; }
    const lines = [];
    for (const l of invoice.lines) {
      const qty = Number(qtyMap[l.variantId] || 0);
      if (qty <= 0) continue;
      const remaining = lineRemaining(l);
      if (qty > remaining) { showToast(`⚠ الكمية المطلوب إرجاعها من "${l.name}" أكبر من المتبقي (${remaining})`, "err"); return; }
      lines.push({ variantId: l.variantId, name: l.name, qty, unitPrice: l.price, unitCost: l.cost, condition: condMap[l.variantId] || "resalable" });
    }
    if (lines.length === 0) { showToast("⚠ حدد كمية إرجاع لسطر واحد على الأقل", "err"); return; }

    const total = lines.reduce((s, l) => s + l.qty * l.unitPrice, 0);
    update((next) => {
      for (const l of lines) {
        if (l.condition === "resalable") {
          pushMovement(next, { variantId: l.variantId, type: "مرتجع بيع", qtyChange: l.qty, unitCost: l.unitCost, ref: `مرتجع فاتورة ${invoice.id}` });
        }
      }
      next.returns.push({ id: uid(), ts: nowISO(), originalInvoiceId: invoiceId, lines, refundMethod, total });
    });
    showToast("✔ تم تسجيل المرتجع");
    setQtyMap({}); setCondMap({}); setInvoiceId("");
  }

  return (
    <div className="rb-grid" style={{ display: "grid", gridTemplateColumns: "300px 1fr", gap: 16 }}>
      <Panel>
        <div style={{ padding: 14, borderBottom: `1px solid ${C.line}`, fontWeight: 800, fontSize: 14.5 }}>اختر الفاتورة الأصلية</div>
        <div style={{ maxHeight: 480, overflow: "auto" }}>
          {recentInvoices.length === 0 && <div style={{ padding: 16, color: C.muted, fontSize: 14 }}>لا توجد فواتير بعد</div>}
          {recentInvoices.map((inv) => (
            <div key={inv.id} onClick={() => setInvoiceId(inv.id)} style={{
              padding: "10px 14px", borderBottom: `1px solid ${C.line}`, cursor: "pointer", fontSize: 13.5,
              background: invoiceId === inv.id ? C.cream : "transparent",
            }}>
              <div style={{ fontWeight: 700 }}>{fmtMoney(inv.total)} ج.م</div>
              <div style={{ color: C.muted, fontSize: 13 }}>{fmtDate(inv.ts)} — {inv.lines.length} صنف</div>
            </div>
          ))}
        </div>
      </Panel>

      <Panel>
        {!invoice ? (
          <div style={{ padding: 30, textAlign: "center", color: C.muted, fontSize: 14.5 }}>اختر فاتورة من القائمة لبدء المرتجع</div>
        ) : (
          <>
            <div style={{ padding: 16, borderBottom: `1px solid ${C.line}`, fontWeight: 800 }}>مرتجع من فاتورة بتاريخ {fmtDate(invoice.ts)}</div>
            <div style={{ padding: 16 }}>
              {invoice.lines.map((l) => {
                const remaining = lineRemaining(l);
                return (
                  <div key={l.variantId} className="rb-grid" style={{ display: "grid", gridTemplateColumns: "2fr 1fr 1fr 1fr", gap: 10, alignItems: "center", padding: "10px 0", borderBottom: `1px solid ${C.line}`, fontSize: 14 }}>
                    <div>
                      <div style={{ fontWeight: 700 }}>{l.name}</div>
                      <div style={{ color: C.muted, fontSize: 13 }}>بيعت: {l.qty} — متبقي قابل للإرجاع: {remaining}</div>
                    </div>
                    <input type="number" min="0" max={remaining} placeholder="كمية الإرجاع" disabled={remaining <= 0}
                      value={qtyMap[l.variantId] || ""} onChange={(e) => setQtyMap((p) => ({ ...p, [l.variantId]: e.target.value }))}
                      style={{ ...inputStyle }} />
                    <select value={condMap[l.variantId] || "resalable"} onChange={(e) => setCondMap((p) => ({ ...p, [l.variantId]: e.target.value }))} style={inputStyle}>
                      <option value="resalable">صالح لإعادة البيع</option>
                      <option value="damaged">تالف</option>
                    </select>
                    <div style={{ fontWeight: 700 }}>{fmtMoney((Number(qtyMap[l.variantId]) || 0) * l.price)} ج.م</div>
                  </div>
                );
              })}
            </div>
            <div style={{ padding: 16, display: "flex", gap: 14, alignItems: "center", borderTop: `1px solid ${C.line}` }}>
              <span style={{ fontSize: 14, fontWeight: 700, color: C.muted }}>طريقة رد المبلغ:</span>
              <select value={refundMethod} onChange={(e) => setRefundMethod(e.target.value)} style={{ ...inputStyle, width: 180 }}>
                <option>كاش</option><option>نفس وسيلة الدفع</option><option>رصيد متجر</option>
              </select>
              <button onClick={submit} style={{ ...smallBtnFilled, marginRight: "auto" }}>تأكيد المرتجع</button>
            </div>
          </>
        )}
      </Panel>
    </div>
  );
}

/* ============================================================
   الجرد
============================================================ */
function StockCountView({ db, update, showToast }) {
  const [actualMap, setActualMap] = useState({});
  const variants = allVariants(db);

  const diffRows = variants
    .filter((v) => actualMap[v.variant.id] !== undefined && actualMap[v.variant.id] !== "")
    .map((v) => ({ ...v, actual: Number(actualMap[v.variant.id]), diff: Number(actualMap[v.variant.id]) - v.qty }))
    .filter((r) => r.diff !== 0);

  function approve() {
    if (diffRows.length === 0) { showToast("⚠ لا توجد فروقات لاعتمادها", "err"); return; }
    update((next) => {
      const countId = uid();
      const lines = [];
      for (const r of diffRows) {
        pushMovement(next, {
          variantId: r.variant.id, type: r.diff > 0 ? "جرد بالزيادة" : "جرد بالنقص",
          qtyChange: r.diff, unitCost: r.variant.costAvg || 0, ref: `دورة جرد ${countId}`,
        });
        lines.push({ variantId: r.variant.id, name: r.product.name, systemQty: r.qty, actualQty: r.actual, difference: r.diff });
      }
      next.stockCounts.push({ id: countId, ts: nowISO(), status: "approved", lines });
    });
    showToast(`✔ تم اعتماد الجرد — ${diffRows.length} صنف تم تصحيحه`);
    setActualMap({});
  }

  return (
    <Panel>
      <div style={{ padding: 16, borderBottom: `1px solid ${C.line}`, fontWeight: 800 }}>
        الجرد — أدخل الكمية الفعلية للأصناف التي تريد جردها فقط، والباقي يبقى بلا تغيير
      </div>
      <div className="rb-table-wrap" style={{ maxHeight: 480, overflow: "auto" }}>
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 14 }}>
          <thead><tr style={{ background: C.cream }}><th style={thStyle}>المنتج</th><th style={thStyle}>الرصيد في النظام</th><th style={thStyle}>الكمية الفعلية</th><th style={thStyle}>الفرق</th></tr></thead>
          <tbody>
            {variants.map((v) => {
              const actual = actualMap[v.variant.id];
              const diff = actual !== undefined && actual !== "" ? Number(actual) - v.qty : null;
              return (
                <tr key={v.variant.id} style={{ borderBottom: `1px solid ${C.line}` }}>
                  <td style={tdStyle}>{v.product.name}{v.variant.attrLabel ? ` — ${v.variant.attrLabel}` : ""}</td>
                  <td style={tdStyle}>{v.qty}</td>
                  <td style={tdStyle}>
                    <input type="number" placeholder={String(v.qty)} value={actual || ""} onChange={(e) => setActualMap((p) => ({ ...p, [v.variant.id]: e.target.value }))} style={{ ...inputStyle, width: 90 }} />
                  </td>
                  <td style={{ ...tdStyle, fontWeight: 800, color: diff === null ? C.muted : diff === 0 ? C.green : diff > 0 ? C.green : C.red }}>
                    {diff === null ? "—" : (diff > 0 ? "+" : "") + diff}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
      <div style={{ padding: 16, borderTop: `1px solid ${C.line}`, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <div style={{ fontSize: 14, color: C.muted }}>{diffRows.length} صنف به فرق — لن يتغير أي رصيد سوى هذه الأصناف عند الاعتماد</div>
        <button onClick={approve} style={smallBtnFilled}>اعتماد الفروقات وتحديث المخزون</button>
      </div>
    </Panel>
  );
}

/* ============================================================
   المصروفات
============================================================ */
function ExpensesView({ db, update, showToast }) {
  const [type, setType] = useState("إيجار");
  const [amount, setAmount] = useState("");
  const [method, setMethod] = useState("كاش");
  const [notes, setNotes] = useState("");
  const [date, setDate] = useState(() => new Date().toISOString().slice(0, 10));
  const [editingExpense, setEditingExpense] = useState(null);
  const submittingRef = useRef(false);

  function add() {
    if (submittingRef.current) return;
    if (!amount || Number(amount) <= 0) { showToast("⚠ أدخل مبلغًا صحيحًا", "err"); return; }
    submittingRef.current = true;
    const amt = Number(amount);
    const chosenDate = date || new Date().toISOString().slice(0, 10);
    const now = new Date();
    const ts = new Date(`${chosenDate}T${String(now.getHours()).padStart(2, "0")}:${String(now.getMinutes()).padStart(2, "0")}:00`).toISOString();
    update((next) => { next.expenses.push({ id: uid(), ts, type, amount: amt, method, notes }); });
    setAmount(""); setNotes("");
    showToast("✔ تم تسجيل المصروف");
    setTimeout(() => { submittingRef.current = false; }, 700);
  }

  const monthTotal = db.expenses.filter((e) => monthKey(e.ts) === currentMonthKey()).reduce((s, e) => s + e.amount, 0);

  return (
    <div className="rb-grid" style={{ display: "grid", gridTemplateColumns: "340px 1fr", gap: 16 }}>
      <Panel>
        <div style={{ padding: 18 }}>
          <div style={{ fontWeight: 800, marginBottom: 14 }}>تسجيل مصروف</div>
          <Field label="النوع">
            <select value={type} onChange={(e) => setType(e.target.value)} style={inputStyle}>
              {["إيجار", "كهرباء", "إنترنت", "تغليف وأكياس", "نقل", "صيانة", "تسويق", "أخرى"].map((t) => <option key={t}>{t}</option>)}
            </select>
          </Field>
          <div style={{ height: 10 }} />
          <Field label="التاريخ (الشهر/السنة)"><input type="date" value={date} onChange={(e) => setDate(e.target.value)} style={inputStyle} /></Field>
          <div style={{ height: 10 }} />
          <Field label="المبلغ"><input type="number" value={amount} onChange={(e) => setAmount(e.target.value)} style={inputStyle} /></Field>
          <div style={{ height: 10 }} />
          <Field label="طريقة الدفع">
            <select value={method} onChange={(e) => setMethod(e.target.value)} style={inputStyle}>
              {PAYMENT_METHODS.map((m) => <option key={m}>{m}</option>)}
            </select>
          </Field>
          <div style={{ height: 10 }} />
          <Field label="ملاحظات (اختياري)"><input value={notes} onChange={(e) => setNotes(e.target.value)} style={inputStyle} /></Field>
          <button onClick={add} style={{ ...smallBtnFilled, width: "100%", marginTop: 16, padding: 12 }}>تسجيل المصروف</button>
        </div>
      </Panel>
      <Panel>
        <div style={{ padding: 16, borderBottom: `1px solid ${C.line}`, fontWeight: 800, display: "flex", justifyContent: "space-between" }}>
          <span>سجل المصروفات</span><span style={{ color: C.plum }}>إجمالي هذا الشهر: {fmtMoney(monthTotal)} ج.م</span>
        </div>
        <div style={{ maxHeight: 480, overflow: "auto" }}>
          {db.expenses.length === 0 && <div style={{ padding: 20, color: C.muted, fontSize: 14, textAlign: "center" }}>لا توجد مصروفات مسجَّلة بعد</div>}
          {[...db.expenses].reverse().map((e) => (
            <div key={e.id} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "10px 16px", borderBottom: `1px solid ${C.line}`, fontSize: 14, gap: 8 }}>
              <div style={{ flex: 1 }}>
                <div style={{ fontWeight: 700 }}>{e.type} {e.notes ? `— ${e.notes}` : ""}</div>
                <div style={{ color: C.muted, fontSize: 13 }}>{fmtDate(e.ts)} — {e.method}</div>
              </div>
              <div style={{ fontWeight: 800, color: C.red }}>− {fmtMoney(e.amount)} ج.م</div>
              <button onClick={() => setEditingExpense(e.id)} title="تعديل" style={{ border: "none", background: "transparent", color: C.plum, cursor: "pointer", padding: 4 }}>
                <Edit2 size={15} />
              </button>
            </div>
          ))}
        </div>
      </Panel>
      {editingExpense && (
        <EditExpenseModal db={db} update={update} showToast={showToast} expenseId={editingExpense} onClose={() => setEditingExpense(null)} />
      )}
    </div>
  );
}

function EditExpenseModal({ db, update, showToast, expenseId, onClose }) {
  const expense = db.expenses.find((e) => e.id === expenseId);
  const [type, setType] = useState(expense?.type || "");
  const [amount, setAmount] = useState(expense?.amount ?? "");
  const [method, setMethod] = useState(expense?.method || "كاش");
  const [notes, setNotes] = useState(expense?.notes || "");
  const [date, setDate] = useState(() => (expense ? expense.ts.slice(0, 10) : new Date().toISOString().slice(0, 10)));

  if (!expense) return null;

  function save() {
    if (!amount || Number(amount) <= 0) { showToast("⚠ أدخل مبلغًا صحيحًا", "err"); return; }
    const oldTime = expense.ts.slice(11, 19);
    const ts = new Date(`${date}T${oldTime}`).toISOString();
    update((next) => {
      const ex = next.expenses.find((e) => e.id === expenseId);
      if (ex) { ex.type = type; ex.amount = Number(amount); ex.method = method; ex.notes = notes; ex.ts = ts; }
    });
    showToast("✔ تم حفظ التعديلات");
    onClose();
  }

  function remove() {
    if (!window.confirm("حذف هذا المصروف؟")) return;
    update((next) => { next.expenses = next.expenses.filter((e) => e.id !== expenseId); });
    showToast("✔ تم حذف المصروف");
    onClose();
  }

  return (
    <div className="no-print" style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,.45)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 100, padding: 16 }}>
      <div style={{ background: "#fff", borderRadius: 16, padding: 24, width: "min(400px,94vw)", maxHeight: "88vh", overflow: "auto", boxShadow: "0 20px 50px rgba(0,0,0,.25)" }}>
        <div style={{ fontWeight: 800, fontSize: 16.5, marginBottom: 16, color: C.plumDeep }}>تعديل المصروف</div>
        <Field label="النوع">
          <select value={type} onChange={(e) => setType(e.target.value)} style={inputStyle}>
            {["إيجار", "كهرباء", "إنترنت", "تغليف وأكياس", "نقل", "صيانة", "تسويق", "أخرى"].map((t) => <option key={t}>{t}</option>)}
          </select>
        </Field>
        <div style={{ height: 10 }} />
        <Field label="التاريخ"><input type="date" value={date} onChange={(e) => setDate(e.target.value)} style={inputStyle} /></Field>
        <div style={{ height: 10 }} />
        <Field label="المبلغ"><input type="number" value={amount} onChange={(e) => setAmount(e.target.value)} style={inputStyle} /></Field>
        <div style={{ height: 10 }} />
        <Field label="طريقة الدفع">
          <select value={method} onChange={(e) => setMethod(e.target.value)} style={inputStyle}>
            {PAYMENT_METHODS.map((m) => <option key={m}>{m}</option>)}
          </select>
        </Field>
        <div style={{ height: 10 }} />
        <Field label="ملاحظات (اختياري)"><input value={notes} onChange={(e) => setNotes(e.target.value)} style={inputStyle} /></Field>
        <div style={{ display: "flex", gap: 8, marginTop: 18 }}>
          <button onClick={save} style={{ ...smallBtnFilled, flex: 1, padding: 12 }}>حفظ التعديلات</button>
          <button onClick={onClose} style={{ ...smallBtnOutline, flex: 1, padding: 12 }}>إلغاء</button>
        </div>
        <button onClick={remove} style={{ width: "100%", marginTop: 10, padding: 10, borderRadius: 10, border: "none", background: "#FDECEA", color: C.red, fontWeight: 700, fontSize: 13, cursor: "pointer" }}>
          حذف المصروف
        </button>
      </div>
    </div>
  );
}

/* ============================================================
   الشركاء وتوزيع الأرباح الشهري
============================================================ */
function buildReceiptText(receipt) {
  const lines = receipt.lines.map((l) => `${l.name}${l.attrLabel ? " — " + l.attrLabel : ""} × ${l.qty} = ${fmtMoney(l.qty * l.price)} ج.م`).join("\n");
  return [
    "🌸 روح",
    `التاريخ: ${fmtDate(receipt.ts)}`,
    receipt.customerName ? `الزبون: ${receipt.customerName}` : null,
    "————————————",
    lines,
    "————————————",
    `الإجمالي: ${fmtMoney(receipt.total)} ج.م`,
    receipt.seller ? `البائع: ${receipt.seller}` : null,
  ].filter(Boolean).join("\n");
}

function ReceiptModal({ receipt, onClose }) {
  const canShare = typeof navigator !== "undefined" && !!navigator.share;

  function handlePrint() {
    document.body.classList.add("rb-printing-receipt");
    window.print();
    setTimeout(() => document.body.classList.remove("rb-printing-receipt"), 500);
  }
  function handleShare() {
    const text = buildReceiptText(receipt);
    if (canShare) {
      navigator.share({ title: "فاتورة روح", text }).catch(() => {});
    }
  }
  function handleWhatsapp() {
    const text = buildReceiptText(receipt);
    const digits = (receipt.customerPhone || "").replace(/[^\d]/g, "");
    const url = digits ? `https://wa.me/${digits}?text=${encodeURIComponent(text)}` : `https://wa.me/?text=${encodeURIComponent(text)}`;
    window.open(url, "_blank");
  }

  return (
    <div className="no-print" style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,.45)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 100, padding: 16 }}>
      <div style={{ background: "#fff", borderRadius: 16, padding: 24, width: "min(380px,92vw)", maxHeight: "88vh", overflow: "auto", boxShadow: "0 20px 50px rgba(0,0,0,.25)" }}>
        <div className="rb-receipt-content">
          <div style={{ textAlign: "center", marginBottom: 14 }}>
            <div style={{ fontWeight: 900, fontSize: 20, color: C.plum }}>روح</div>
            <div style={{ fontSize: 12, color: C.muted, marginTop: 2 }}>{fmtDate(receipt.ts)}</div>
            {receipt.customerName && <div style={{ fontSize: 12.5, color: C.ink, marginTop: 4 }}>الزبون: {receipt.customerName}</div>}
          </div>
          <div style={{ borderTop: `1.5px dashed ${C.line}`, borderBottom: `1.5px dashed ${C.line}`, padding: "10px 0", marginBottom: 12 }}>
            {receipt.lines.map((l, i) => (
              <div key={i} style={{ display: "flex", justifyContent: "space-between", fontSize: 13.5, padding: "4px 0" }}>
                <span>{l.name}{l.attrLabel ? ` — ${l.attrLabel}` : ""} × {l.qty}</span>
                <span style={{ fontWeight: 700 }}>{fmtMoney(l.qty * l.price)}</span>
              </div>
            ))}
          </div>
          <div style={{ display: "flex", justifyContent: "space-between", fontWeight: 800, fontSize: 16.5, marginBottom: 4 }}>
            <span>الإجمالي</span>
            <span>{fmtMoney(receipt.total)} ج.م</span>
          </div>
          {receipt.seller && <div style={{ fontSize: 11.5, color: C.muted, textAlign: "center", marginTop: 10 }}>البائع: {receipt.seller}</div>}
        </div>

        <div style={{ display: "flex", gap: 8, marginTop: 18, flexWrap: "wrap" }}>
          <button onClick={handlePrint} style={{ flex: "1 1 100px", display: "flex", alignItems: "center", justifyContent: "center", gap: 6, padding: "10px", borderRadius: 10, border: `1.5px solid ${C.line}`, background: "#fff", color: C.ink, fontWeight: 700, fontSize: 13, cursor: "pointer" }}>
            <Printer size={16} /> طباعة / PDF
          </button>
          <button onClick={handleWhatsapp} style={{ flex: "1 1 100px", display: "flex", alignItems: "center", justifyContent: "center", gap: 6, padding: "10px", borderRadius: 10, border: "none", background: "#25D366", color: "#fff", fontWeight: 700, fontSize: 13, cursor: "pointer" }}>
            <MessageCircle size={16} /> واتساب
          </button>
          {canShare && (
            <button onClick={handleShare} style={{ flex: "1 1 100px", display: "flex", alignItems: "center", justifyContent: "center", gap: 6, padding: "10px", borderRadius: 10, border: "none", background: C.plum, color: "#fff", fontWeight: 700, fontSize: 13, cursor: "pointer" }}>
              <Share2 size={16} /> مشاركة
            </button>
          )}
        </div>
        <button onClick={onClose} style={{ width: "100%", marginTop: 10, padding: 10, borderRadius: 10, border: "none", background: C.cream, color: C.muted, fontWeight: 700, fontSize: 13, cursor: "pointer" }}>
          إغلاق — فاتورة جديدة
        </button>
      </div>
    </div>
  );
}

/* ============================================================
   العملاء — سجل الزبائن وتاريخ طلباتهم
============================================================ */
function CustomersView({ db, update, showToast }) {
  const [query, setQuery] = useState("");
  const [expandedId, setExpandedId] = useState(null);

  const rows = useMemo(() => {
    const customers = db.customers || [];
    return customers.map((c) => {
      const orders = db.invoices.filter((i) => i.customerId === c.id);
      const totalSpent = orders.reduce((s, i) => s + i.total, 0);
      const lastOrder = orders.length ? orders.reduce((a, b) => (a.ts > b.ts ? a : b)) : null;
      return { ...c, orderCount: orders.length, totalSpent, lastOrder, orders };
    }).sort((a, b) => (b.lastOrder?.ts || "").localeCompare(a.lastOrder?.ts || ""));
  }, [db.customers, db.invoices]);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return rows;
    return rows.filter((c) => (c.name || "").toLowerCase().includes(q) || c.phone.includes(q));
  }, [rows, query]);

  return (
    <div>
      <h2 style={{ fontSize: 18.5, fontWeight: 800, color: C.plumDeep, marginBottom: 16 }}>العملاء</h2>
      <div style={{ marginBottom: 14 }}>
        <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="ابحث بالاسم أو رقم الجوال..."
          style={{ ...inputStyle, maxWidth: 320 }} />
      </div>
      {filtered.length === 0 ? (
        <Panel><EmptyState icon={Contact} text="لا يوجد عملاء مسجّلين بعد — يُضافون تلقائيًا عند تسجيل رقم الزبون بنقطة البيع" /></Panel>
      ) : (
        <Panel>
          <div className="rb-table-wrap" style={{ overflow: "auto" }}>
            <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 14 }}>
              <thead>
                <tr>
                  <th style={thStyle}>الاسم</th>
                  <th style={thStyle}>الجوال</th>
                  <th style={thStyle}>عدد الطلبات</th>
                  <th style={thStyle}>إجمالي المشتريات</th>
                  <th style={thStyle}>آخر طلب</th>
                </tr>
              </thead>
              <tbody>
                {filtered.map((c) => (
                  <React.Fragment key={c.id}>
                    <tr onClick={() => setExpandedId(expandedId === c.id ? null : c.id)} style={{ cursor: "pointer", borderTop: `1px solid ${C.line}` }}>
                      <td style={{ ...tdStyle, fontWeight: 700 }}>{c.name || "بدون اسم"}</td>
                      <td style={tdStyle}>{c.phone}</td>
                      <td style={tdStyle}>{c.orderCount}</td>
                      <td style={{ ...tdStyle, fontWeight: 700, color: C.green }}>{fmtMoney(c.totalSpent)} ج.م</td>
                      <td style={tdStyle}>{c.lastOrder ? fmtDate(c.lastOrder.ts) : "—"}</td>
                    </tr>
                    {expandedId === c.id && (
                      <tr>
                        <td colSpan={5} style={{ padding: "10px 16px", background: C.cream }}>
                          {c.orders.length === 0 ? (
                            <div style={{ color: C.muted, fontSize: 13 }}>ما فيه طلبات مسجّلة لهذا العميل</div>
                          ) : (
                            <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
                              {c.orders.sort((a, b) => b.ts.localeCompare(a.ts)).map((o) => (
                                <div key={o.id} style={{ display: "flex", justifyContent: "space-between", fontSize: 12.5, padding: "6px 0", borderBottom: `1px solid ${C.line}` }}>
                                  <span>{fmtDate(o.ts)}</span>
                                  <span style={{ color: C.muted }}>{o.lines.map((l) => l.name).join("، ")}</span>
                                  <span style={{ fontWeight: 700 }}>{fmtMoney(o.total)} ج.م</span>
                                </div>
                              ))}
                            </div>
                          )}
                        </td>
                      </tr>
                    )}
                  </React.Fragment>
                ))}
              </tbody>
            </table>
          </div>
        </Panel>
      )}
    </div>
  );
}


function PartnersView({ db, update, showToast }) {
  const period = currentMonthKey();
  const fin = computeMonthFinancials(db, period);
  const alreadyClosed = db.periodClosures.find((p) => p.periodLabel === period);
  const [payAmount, setPayAmount] = useState({});
  const [expandedHistory, setExpandedHistory] = useState({});

  const now = new Date();
  const [histMonth, setHistMonth] = useState(String(now.getMonth() + 1).padStart(2, "0"));
  const [histYear, setHistYear] = useState(String(now.getFullYear()));
  const [histMode, setHistMode] = useState("detailed"); // "detailed" | "grossOnly"
  const [histSales, setHistSales] = useState("");
  const [histCost, setHistCost] = useState("");
  const [histGrossDirect, setHistGrossDirect] = useState("");
  const [histExpenses, setHistExpenses] = useState("");
  const histPeriodLabel = `${histYear}-${histMonth}`;
  const histDisplayLabel = `${ARABIC_MONTHS[Number(histMonth) - 1]} ${histYear}`;
  const histGross = histMode === "detailed" ? (Number(histSales) || 0) - (Number(histCost) || 0) : (Number(histGrossDirect) || 0);
  const histNet = histGross - (Number(histExpenses) || 0);

  function closeMonth() {
    if (alreadyClosed) { showToast("⚠ هذا الشهر مُعتمَد بالفعل", "err"); return; }
    if (fin.netProfit <= 0) { showToast("⚠ لا يوجد ربح موجب لتوزيعه هذا الشهر", "err"); return; }
    update((next) => {
      next.periodClosures.push({ id: uid(), periodLabel: period, displayLabel: `${ARABIC_MONTHS[now.getMonth()]} ${now.getFullYear()}`, netProfit: fin.netProfit, sales: fin.netSales, cost: fin.cogs, grossProfit: fin.grossProfit, expenses: fin.totalExpenses, closedAt: nowISO() });
      for (const p of next.partners) {
        const share = (fin.netProfit * p.percentage) / 100;
        next.partnerTransactions.push({ id: uid(), ts: nowISO(), partnerId: p.id, type: "accrued", amount: share, periodLabel: period, notes: `ربح شهر ${period}` });
      }
    });
    showToast("✔ تم اعتماد الشهر وتوزيع الربح المستحق على الشركاء");
  }

  function closeHistoricalMonth() {
    if (histMode === "detailed" && (!histSales || Number(histSales) <= 0)) { showToast("⚠ أدخل إجمالي المبيعات", "err"); return; }
    if (histMode === "detailed" && histCost === "") { showToast("⚠ أدخل إجمالي التكلفة (الجملة)", "err"); return; }
    if (histMode === "grossOnly" && (!histGrossDirect || Number(histGrossDirect) === 0)) { showToast("⚠ أدخل الربح الإجمالي", "err"); return; }
    if (db.periodClosures.some((p) => p.periodLabel === histPeriodLabel)) { showToast("⚠ هذا الشهر مُدخَل بالفعل", "err"); return; }
    update((next) => {
      next.periodClosures.push({
        id: uid(), periodLabel: histPeriodLabel, displayLabel: histDisplayLabel, netProfit: histNet, closedAt: nowISO(),
        isHistorical: true,
        sales: histMode === "detailed" ? Number(histSales) : null,
        cost: histMode === "detailed" ? Number(histCost) : null,
        grossProfit: histGross,
        expenses: Number(histExpenses) || 0,
      });
      for (const p of next.partners) {
        const share = (histNet * p.percentage) / 100;
        next.partnerTransactions.push({ id: uid(), ts: nowISO(), partnerId: p.id, type: "accrued", amount: share, periodLabel: histPeriodLabel, notes: `ربح تاريخي — ${histDisplayLabel}` });
      }
    });
    showToast(`✔ تم إدخال بيانات ${histDisplayLabel} وتوزيع الربح على الشركاء`);
    setHistSales(""); setHistCost(""); setHistGrossDirect(""); setHistExpenses("");
  }

  function payPartner(partnerId, amountOverride, periodLabel) {
    const amt = Number(amountOverride ?? payAmount[partnerId] ?? 0);
    if (amt <= 0) { showToast("⚠ أدخل مبلغًا صحيحًا", "err"); return; }
    update((next) => {
      next.partnerTransactions.push({
        id: uid(), ts: nowISO(), partnerId, type: "paid", amount: amt,
        periodLabel: periodLabel || undefined,
        notes: periodLabel ? `دفعة فعلية — ${periodLabel}` : "دفعة فعلية",
      });
    });
    if (!periodLabel) setPayAmount((p) => ({ ...p, [partnerId]: "" }));
    showToast("✔ تم تسجيل الدفعة");
  }

  return (
    <div>
      <Panel>
        <div style={{ padding: 18 }}>
          <div style={{ fontWeight: 800, marginBottom: 12 }}>معاينة نتيجة الشهر الحالي ({period})</div>
          <div className="rb-grid" style={{ display: "grid", gridTemplateColumns: "repeat(3,1fr)", gap: 10, marginBottom: 16 }}>
            <MiniStat label="صافي المبيعات" val={fmtMoney(fin.netSales)} />
            <MiniStat label="مجمل الربح" val={fmtMoney(fin.grossProfit)} />
            <MiniStat label="المصروفات" val={`− ${fmtMoney(fin.totalExpenses)}`} />
          </div>
          <div style={{ background: C.cream, borderRadius: 12, padding: 14, display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
            <span style={{ fontWeight: 800, fontSize: 16 }}>صافي الربح القابل للتوزيع</span>
            <span style={{ fontWeight: 800, fontSize: 19.5, color: fin.netProfit >= 0 ? C.green : C.red }}>{fmtMoney(fin.netProfit)} ج.م</span>
          </div>
          {alreadyClosed ? (
            <div style={{ fontSize: 14, color: C.green, fontWeight: 700 }}>✔ هذا الشهر مُعتمَد بالفعل بتاريخ {fmtDate(alreadyClosed.closedAt)}</div>
          ) : (
            <button onClick={closeMonth} style={{ ...smallBtnFilled, padding: "11px 24px" }}>اعتماد الشهر وتوزيع الربح على الشركاء</button>
          )}
          <div style={{ fontSize: 13, color: C.muted, marginTop: 10 }}>
            الاعتماد يُسجّل الربح "المستحق" لكل شريك فقط — لا يُخرج أي نقد فعليًا من الصندوق. تسجيل الدفع الفعلي يتم بشكل منفصل أدناه.
          </div>
        </div>
      </Panel>

      <Panel>
        <div style={{ padding: 18 }}>
          <div style={{ fontWeight: 800, marginBottom: 4 }}>إدخال شهر سابق (قبل استخدام النظام)</div>
          <div style={{ fontSize: 13, color: C.muted, marginBottom: 14 }}>
            أدخل إجمالي مبيعات وتكلفة ومصروفات الشهر كأرقام كاملة — دون التأثير على المخزون الفعلي أو إنشاء منتجات وهمية.
          </div>
          <div style={{ display: "flex", gap: 8, marginBottom: 12 }}>
            <button onClick={() => setHistMode("detailed")} style={{
              padding: "7px 14px", borderRadius: 9, border: `1.5px solid ${histMode === "detailed" ? C.plum : C.line}`,
              background: histMode === "detailed" ? C.plum : "#fff", color: histMode === "detailed" ? "#fff" : C.muted, fontWeight: 700, fontSize: 13.5, cursor: "pointer",
            }}>عندي مبيعات وتكلفة منفصلة</button>
            <button onClick={() => setHistMode("grossOnly")} style={{
              padding: "7px 14px", borderRadius: 9, border: `1.5px solid ${histMode === "grossOnly" ? C.plum : C.line}`,
              background: histMode === "grossOnly" ? C.plum : "#fff", color: histMode === "grossOnly" ? "#fff" : C.muted, fontWeight: 700, fontSize: 13.5, cursor: "pointer",
            }}>عندي الربح الإجمالي فقط</button>
          </div>
          <div className="rb-grid" style={{ display: "grid", gridTemplateColumns: histMode === "detailed" ? "repeat(5,1fr)" : "repeat(4,1fr)", gap: 10, marginBottom: 12 }}>
            <Field label="الشهر">
              <select value={histMonth} onChange={(e) => setHistMonth(e.target.value)} style={inputStyle}>
                {ARABIC_MONTHS.map((m, i) => <option key={m} value={String(i + 1).padStart(2, "0")}>{m}</option>)}
              </select>
            </Field>
            <Field label="السنة"><input type="number" value={histYear} onChange={(e) => setHistYear(e.target.value)} style={inputStyle} /></Field>
            {histMode === "detailed" ? (
              <>
                <Field label="إجمالي المبيعات"><input type="number" value={histSales} onChange={(e) => setHistSales(e.target.value)} style={inputStyle} /></Field>
                <Field label="إجمالي التكلفة (الجملة)"><input type="number" value={histCost} onChange={(e) => setHistCost(e.target.value)} style={inputStyle} /></Field>
              </>
            ) : (
              <Field label="الربح الإجمالي (قبل المصروفات)"><input type="number" value={histGrossDirect} onChange={(e) => setHistGrossDirect(e.target.value)} style={inputStyle} /></Field>
            )}
            <Field label="إجمالي المصروفات"><input type="number" value={histExpenses} onChange={(e) => setHistExpenses(e.target.value)} style={inputStyle} /></Field>
          </div>
          {(histSales || histCost || histGrossDirect) && (
            <div className="rb-grid" style={{ display: "grid", gridTemplateColumns: "repeat(2,1fr)", gap: 10, marginBottom: 14 }}>
              <MiniStat label="الربح الإجمالي (مبيعات − تكلفة)" val={fmtMoney(histGross)} />
              <MiniStat label="صافي الربح القابل للتوزيع (بعد المصروفات)" val={fmtMoney(histNet)} />
            </div>
          )}
          <button onClick={closeHistoricalMonth} style={smallBtnFilled}>حفظ الشهر وتوزيع الربح على الشركاء</button>

          {db.periodClosures.filter((p) => p.isHistorical).length > 0 && (
            <div style={{ marginTop: 16, borderTop: `1px solid ${C.line}`, paddingTop: 12 }}>
              <div style={{ fontSize: 13.5, fontWeight: 700, color: C.muted, marginBottom: 8 }}>الأشهر التاريخية المُدخَلة</div>
              {db.periodClosures.filter((p) => p.isHistorical).map((p) => (
                <div key={p.id} style={{ display: "flex", justifyContent: "space-between", padding: "8px 0", borderBottom: `1px solid ${C.line}`, fontSize: 14 }}>
                  <span style={{ fontWeight: 700 }}>{p.displayLabel || p.periodLabel}</span>
                  <span style={{ color: C.muted }}>
                    {p.sales != null ? `مبيعات ${fmtMoney(p.sales)} — تكلفة ${fmtMoney(p.cost)} — ` : ""}
                    مصروفات {fmtMoney(p.expenses)}
                  </span>
                  <span style={{ fontWeight: 800, color: C.green }}>صافي {fmtMoney(p.netProfit)}</span>
                </div>
              ))}
            </div>
          )}
        </div>
      </Panel>

      <div className="rb-grid" style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16, marginTop: 16 }}>
        {db.partners.map((p) => {
          const balance = partnerBalance(db, p.id);
          return (
            <Panel key={p.id}>
              <div style={{ padding: 16 }}>
                <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 10 }}>
                  <span style={{ fontWeight: 800, fontSize: 16 }}>{p.name}</span>
                  <span style={{ fontSize: 13.5, background: C.plum, color: "#fff", padding: "3px 10px", borderRadius: 20, fontWeight: 700 }}>{p.percentage}%</span>
                </div>
                <div style={{ fontSize: 14, color: C.muted, marginBottom: 4 }}>الرصيد المستحق (غير مدفوع بعد)</div>
                <div style={{ fontSize: 20.5, fontWeight: 800, color: C.green, marginBottom: 14 }}>{fmtMoney(balance)} ج.م</div>
                <div style={{ display: "flex", gap: 8 }}>
                  <input type="number" placeholder="مبلغ الدفعة" value={payAmount[p.id] || ""} onChange={(e) => setPayAmount((prev) => ({ ...prev, [p.id]: e.target.value }))} style={{ ...inputStyle, flex: 1 }} />
                  <button onClick={() => payPartner(p.id)} style={smallBtnOutline}>تسجيل دفعة فعلية</button>
                </div>
                <button onClick={() => setExpandedHistory((prev) => ({ ...prev, [p.id]: !prev[p.id] }))} style={{
                  width: "100%", marginTop: 12, padding: 8, borderRadius: 8, border: "none", background: "transparent",
                  color: C.plum, fontWeight: 700, fontSize: 12.5, cursor: "pointer",
                }}>
                  {expandedHistory[p.id] ? "▲ إخفاء سجل الاستحقاقات" : "▼ عرض سجل الاستحقاقات شهر بشهر"}
                </button>
                {expandedHistory[p.id] && (
                  <>
                    <PartnerHistoryTable db={db} update={update} showToast={showToast} partnerId={p.id} percentage={p.percentage} />
                    <PartnerPaymentsLog db={db} update={update} showToast={showToast} partnerId={p.id} />
                  </>
                )}
              </div>
            </Panel>
          );
        })}
      </div>
    </div>
  );
}
function PartnerPaymentsLog({ db, update, showToast, partnerId }) {
  const payments = (db.partnerTransactions || [])
    .filter((t) => t.partnerId === partnerId && t.type === "paid")
    .sort((a, b) => b.ts.localeCompare(a.ts));

  function deletePayment(id) {
    if (!window.confirm("حذف هذه الدفعة؟ المبلغ يرجع للرصيد المستحق (غير مدفوع).")) return;
    update((next) => {
      next.partnerTransactions = next.partnerTransactions.filter((t) => t.id !== id);
    });
    showToast("✔ تم حذف الدفعة");
  }

  if (payments.length === 0) return null;

  return (
    <div style={{ marginTop: 14, borderTop: `1px solid ${C.line}`, paddingTop: 14 }}>
      <div style={{ fontWeight: 800, fontSize: 14, marginBottom: 8 }}>سجل الدفعات المسجّلة</div>
      {payments.map((p) => (
        <div key={p.id} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "7px 0", borderBottom: `1px solid ${C.line}`, fontSize: 12.5, gap: 8 }}>
          <span style={{ color: C.muted, flex: 1 }}>{fmtDate(p.ts)}{p.periodLabel ? ` — ${p.notes || p.periodLabel}` : ""}</span>
          <span style={{ fontWeight: 700, color: C.green }}>{fmtMoney(p.amount)} ج.م</span>
          <button onClick={() => deletePayment(p.id)} title="حذف الدفعة" style={{ border: "none", background: "transparent", color: C.red, cursor: "pointer", padding: 4 }}>
            <Trash2 size={15} />
          </button>
        </div>
      ))}
    </div>
  );
}

function PartnerHistoryTable({ db, update, showToast, partnerId, percentage }) {
  const { rows, extraPaid } = useMemo(() => computePartnerHistory(db, partnerId), [db, partnerId]);
  const years = useMemo(() => {
    const set = new Set(rows.map((r) => (r.periodLabel || "").split("-")[0]).filter(Boolean));
    return Array.from(set).sort().reverse();
  }, [rows]);
  const [yearFilter, setYearFilter] = useState("all");
  const [payDraft, setPayDraft] = useState({});

  const filtered = yearFilter === "all" ? rows : rows.filter((r) => (r.periodLabel || "").startsWith(yearFilter));
  const totals = filtered.reduce((s, r) => ({ accrued: s.accrued + r.accrued, paid: s.paid + r.paid, remaining: s.remaining + r.remaining }), { accrued: 0, paid: 0, remaining: 0 });

  const statusLabel = { paid: "مدفوع بالكامل", partial: "مدفوع جزئيًا", unpaid: "غير مدفوع" };
  const statusColor = { paid: C.green, partial: C.amber, unpaid: C.red };

  function payForMonth(periodLabel, maxRemaining) {
    const amt = Number(payDraft[periodLabel] || 0);
    if (!amt || amt <= 0) { showToast("⚠ أدخل مبلغًا صحيحًا", "err"); return; }
    if (amt > maxRemaining + 0.01) { showToast("⚠ المبلغ أكبر من المتبقي لهذا الشهر", "err"); return; }
    update((next) => {
      next.partnerTransactions.push({ id: uid(), ts: nowISO(), partnerId, type: "paid", amount: amt, periodLabel, notes: `دفعة لشهر محدد` });
    });
    setPayDraft((p) => ({ ...p, [periodLabel]: "" }));
    showToast("✔ تم تسجيل الدفعة لهذا الشهر");
  }

  return (
    <div style={{ marginTop: 14, borderTop: `1px solid ${C.line}`, paddingTop: 14 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
        <div style={{ fontWeight: 800, fontSize: 14 }}>سجل الاستحقاقات ({percentage}% من كل شهر)</div>
        <select value={yearFilter} onChange={(e) => setYearFilter(e.target.value)} style={{ padding: "5px 8px", borderRadius: 8, border: `1px solid ${C.line}`, fontFamily: "inherit", fontSize: 12.5 }}>
          <option value="all">كل الفترات</option>
          {years.map((y) => <option key={y} value={y}>{y}</option>)}
        </select>
      </div>

      {filtered.length === 0 ? (
        <div style={{ fontSize: 13, color: C.muted, textAlign: "center", padding: "12px 0" }}>ما فيه استحقاقات مسجّلة {yearFilter !== "all" ? `لسنة ${yearFilter}` : "بعد"}</div>
      ) : (
        <div className="rb-table-wrap" style={{ overflow: "auto" }}>
          <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12.5 }}>
            <thead>
              <tr>
                <th style={thStyle}>الشهر</th>
                <th style={thStyle}>المستحق</th>
                <th style={thStyle}>المدفوع</th>
                <th style={thStyle}>المتبقي</th>
                <th style={thStyle}>الحالة</th>
                <th style={thStyle}>دفع لهذا الشهر</th>
              </tr>
            </thead>
            <tbody>
              {filtered.map((r) => (
                <tr key={r.periodLabel} style={{ borderTop: `1px solid ${C.line}` }}>
                  <td style={{ ...tdStyle, fontWeight: 700 }}>{r.displayLabel}</td>
                  <td style={tdStyle}>{fmtMoney(r.accrued)}</td>
                  <td style={{ ...tdStyle, color: C.green }}>{fmtMoney(r.paid)}</td>
                  <td style={{ ...tdStyle, color: r.remaining > 0.01 ? C.red : C.muted, fontWeight: 700 }}>{fmtMoney(r.remaining)}</td>
                  <td style={{ ...tdStyle, color: statusColor[r.status], fontWeight: 700 }}>{statusLabel[r.status]}</td>
                  <td style={tdStyle}>
                    {r.remaining > 0.01 ? (
                      <div style={{ display: "flex", gap: 4 }}>
                        <input type="number" placeholder={fmtMoney(r.remaining)} value={payDraft[r.periodLabel] || ""}
                          onChange={(e) => setPayDraft((p) => ({ ...p, [r.periodLabel]: e.target.value }))}
                          style={{ width: 80, padding: "4px 6px", borderRadius: 6, border: `1px solid ${C.line}`, fontFamily: "inherit", fontSize: 12 }} />
                        <button onClick={() => payForMonth(r.periodLabel, r.remaining)} style={{
                          padding: "4px 8px", borderRadius: 6, border: "none", background: C.plum, color: "#fff", fontWeight: 700, fontSize: 11.5, cursor: "pointer",
                        }}>دفع</button>
                      </div>
                    ) : <span style={{ color: C.muted, fontSize: 12 }}>—</span>}
                  </td>
                </tr>
              ))}
            </tbody>
            <tfoot>
              <tr style={{ borderTop: `2px solid ${C.line}`, fontWeight: 800 }}>
                <td style={tdStyle}>الإجمالي</td>
                <td style={tdStyle}>{fmtMoney(totals.accrued)}</td>
                <td style={{ ...tdStyle, color: C.green }}>{fmtMoney(totals.paid)}</td>
                <td style={{ ...tdStyle, color: totals.remaining > 0.01 ? C.red : C.muted }}>{fmtMoney(totals.remaining)}</td>
                <td style={tdStyle}></td>
                <td style={tdStyle}></td>
              </tr>
            </tfoot>
          </table>
        </div>
      )}
      {extraPaid > 0.01 && (
        <div style={{ fontSize: 12, color: C.muted, marginTop: 8 }}>
          + دفعة مقدّمة زايدة عن كل الاستحقاقات المسجّلة حاليًا: <b style={{ color: C.green }}>{fmtMoney(extraPaid)} ج.م</b>
        </div>
      )}
    </div>
  );
}

function MiniStat({ label, val }) {
  return (
    <div style={{ background: C.cream, borderRadius: 10, padding: 12 }}>
      <div style={{ fontSize: 12.5, color: C.muted, fontWeight: 500, marginBottom: 4 }}>{label}</div>
      <div style={{ fontWeight: 900, fontSize: 16 }}>{val}</div>
    </div>
  );
}

/* ============================================================
   التقارير — شهري / ربع سنوي / سنوي / فترة مخصصة
============================================================ */
function ReportsView({ db }) {
  const [mode, setMode] = useState("monthly"); // monthly | quarterly | annual | custom
  const allRows = useMemo(() => getAllPeriodRows(db), [db]);
  const [fromP, setFromP] = useState(allRows[0]?.periodLabel || currentMonthKey());
  const [toP, setToP] = useState(allRows[allRows.length - 1]?.periodLabel || currentMonthKey());

  let displayRows = [];
  if (mode === "monthly") displayRows = allRows;
  else if (mode === "quarterly") displayRows = aggregateByQuarter(allRows);
  else if (mode === "annual") displayRows = aggregateByYear(allRows);
  else if (mode === "custom") displayRows = allRows.filter((r) => r.periodLabel >= fromP && r.periodLabel <= toP);

  const totals = sumRows(displayRows);

  function exportExcel() {
    const rows = displayRows.map((r) => {
      const row = {
        "الفترة": r.displayLabel,
        "المبيعات": r.sales || 0,
        "التكلفة (الجملة)": r.cogs || 0,
        "المصروفات": r.expenses || 0,
        "صافي الربح": r.netProfit || 0,
      };
      db.partners.forEach((p) => { row[`نصيب ${p.name} (${p.percentage}%)`] = Math.round(((r.netProfit || 0) * p.percentage) / 100 * 100) / 100; });
      return row;
    });
    const totalRow = {
      "الفترة": "الإجمالي",
      "المبيعات": totals.sales || 0,
      "التكلفة (الجملة)": totals.cogs || 0,
      "المصروفات": totals.expenses || 0,
      "صافي الربح": totals.netProfit || 0,
    };
    db.partners.forEach((p) => { totalRow[`نصيب ${p.name} (${p.percentage}%)`] = Math.round(((totals.netProfit || 0) * p.percentage) / 100 * 100) / 100; });
    rows.push(totalRow);
    const ws = XLSX.utils.json_to_sheet(rows);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "التقرير");
    const modeLabel = { monthly: "شهري", quarterly: "ربع_سنوي", annual: "سنوي", custom: "مخصص" }[mode] || mode;
    XLSX.writeFile(wb, `تقرير_روح_${modeLabel}.xlsx`);
  }

  function printReport() {
    window.print();
  }

  return (
    <div>
      <div className="no-print" style={{ display: "flex", gap: 8, marginBottom: 16, flexWrap: "wrap", alignItems: "center" }}>
        {[["monthly", "شهري"], ["quarterly", "ربع سنوي"], ["annual", "سنوي"], ["custom", "فترة مخصصة"]].map(([id, label]) => (
          <button key={id} onClick={() => setMode(id)} style={{
            padding: "8px 16px", borderRadius: 10, border: `1.5px solid ${mode === id ? C.plum : C.line}`,
            background: mode === id ? C.plum : "#fff", color: mode === id ? "#fff" : C.muted, fontWeight: 700, fontSize: 14.5, cursor: "pointer",
          }}>{label}</button>
        ))}
        <div style={{ flex: 1 }} />
        <button onClick={exportExcel} style={{
          display: "flex", alignItems: "center", gap: 6, padding: "8px 14px", borderRadius: 10, border: `1.5px solid ${C.green}`,
          background: "#fff", color: C.green, fontWeight: 700, fontSize: 14.5, cursor: "pointer",
        }}><FileDown size={17} /> تصدير Excel</button>
        <button onClick={printReport} style={{
          display: "flex", alignItems: "center", gap: 6, padding: "8px 14px", borderRadius: 10, border: `1.5px solid ${C.plum}`,
          background: "#fff", color: C.plum, fontWeight: 700, fontSize: 14.5, cursor: "pointer",
        }}><Printer size={17} /> طباعة / حفظ PDF</button>
        {mode === "custom" && (
          <>
            <span style={{ fontSize: 13.5, color: C.muted, fontWeight: 700 }}>من</span>
            <select value={fromP} onChange={(e) => setFromP(e.target.value)} style={{ ...inputStyle, width: 160 }}>
              {allRows.map((r) => <option key={r.periodLabel} value={r.periodLabel}>{r.displayLabel}</option>)}
            </select>
            <span style={{ fontSize: 13.5, color: C.muted, fontWeight: 700 }}>إلى</span>
            <select value={toP} onChange={(e) => setToP(e.target.value)} style={{ ...inputStyle, width: 160 }}>
              {allRows.map((r) => <option key={r.periodLabel} value={r.periodLabel}>{r.displayLabel}</option>)}
            </select>
          </>
        )}
      </div>

      <Panel>
        <div className="rb-table-wrap" style={{ overflow: "auto" }}>
          <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 14 }}>
            <thead>
              <tr style={{ background: C.cream }}>
                <th style={thStyle}>الفترة</th>
                <th style={thStyle}>المبيعات</th>
                <th style={thStyle}>التكلفة (الجملة)</th>
                <th style={thStyle}>المصروفات</th>
                <th style={thStyle}>صافي الربح</th>
                {db.partners.map((p) => <th key={p.id} style={thStyle}>نصيب {p.name} ({p.percentage}%)</th>)}
              </tr>
            </thead>
            <tbody>
              {displayRows.length === 0 && (
                <tr><td colSpan={5 + db.partners.length} style={{ textAlign: "center", padding: 30, color: C.muted }}>لا توجد بيانات لهذه الفترة</td></tr>
              )}
              {displayRows.map((r) => (
                <tr key={r.periodLabel || r.key} style={{ borderBottom: `1px solid ${C.line}` }}>
                  <td style={{ ...tdStyle, fontWeight: 700 }}>{r.displayLabel}{r.closed === false ? <span style={{ fontSize: 12, color: C.amber, marginRight: 6 }}>(جارٍ)</span> : ""}</td>
                  <td style={tdStyle}>{fmtMoney(r.sales)}</td>
                  <td style={tdStyle}>{fmtMoney(r.cogs)}</td>
                  <td style={tdStyle}>{fmtMoney(r.expenses)}</td>
                  <td style={{ ...tdStyle, fontWeight: 800, color: r.netProfit >= 0 ? C.green : C.red }}>{fmtMoney(r.netProfit)}</td>
                  {db.partners.map((p) => <td key={p.id} style={tdStyle}>{fmtMoney((r.netProfit * p.percentage) / 100)}</td>)}
                </tr>
              ))}
            </tbody>
            {displayRows.length > 0 && (
              <tfoot>
                <tr style={{ background: C.cream, borderTop: `2px solid ${C.line}` }}>
                  <td style={{ ...tdStyle, fontWeight: 900 }}>الإجمالي</td>
                  <td style={{ ...tdStyle, fontWeight: 900 }}>{fmtMoney(totals.sales)}</td>
                  <td style={{ ...tdStyle, fontWeight: 900 }}>{fmtMoney(totals.cogs)}</td>
                  <td style={{ ...tdStyle, fontWeight: 900 }}>{fmtMoney(totals.expenses)}</td>
                  <td style={{ ...tdStyle, fontWeight: 900, color: C.green }}>{fmtMoney(totals.netProfit)}</td>
                  {db.partners.map((p) => <td key={p.id} style={{ ...tdStyle, fontWeight: 900 }}>{fmtMoney((totals.netProfit * p.percentage) / 100)}</td>)}
                </tr>
              </tfoot>
            )}
          </table>
        </div>
      </Panel>
    </div>
  );
}

/* ============================================================
   عناصر مشتركة
============================================================ */
function Panel({ children }) {
  return <div className="rb-panel" style={{ background: "#fff", borderRadius: 16, border: `1px solid ${C.line}`, boxShadow: "0 1px 3px rgba(0,0,0,.05)" }}>{children}</div>;
}
function Field({ label, children }) {
  return <div style={{ display: "flex", flexDirection: "column", gap: 6 }}><label style={{ fontSize: 13, fontWeight: 500, color: C.muted }}>{label}</label>{children}</div>;
}
const inputStyle = { padding: "9px 12px", border: `1.5px solid ${C.line}`, borderRadius: 9, fontSize: 14.5, width: "100%", fontFamily: "inherit" };
const thStyle = { padding: "9px 10px", textAlign: "right", color: C.muted, fontSize: 13, fontWeight: 600, letterSpacing: "0.01em", borderBottom: `1.5px solid ${C.line}` };
const tdStyle = { padding: "8px 10px" };
const smallBtnFilled = { padding: "9px 18px", borderRadius: 10, border: "none", background: C.plum, color: "#fff", fontWeight: 700, fontSize: 14, letterSpacing: "0.01em", cursor: "pointer", boxShadow: "0 1px 2px rgba(0,0,0,.08)" };
const smallBtnOutline = { padding: "9px 18px", borderRadius: 10, border: `1.5px solid ${C.line}`, background: "#fff", color: C.muted, fontWeight: 700, fontSize: 14, letterSpacing: "0.01em", cursor: "pointer" };
